-- NEXORA FORGE ACADEMY: 324-lesson curriculum (36 per course)
-- Archives old published lessons without deleting records or student history.
-- Safe to rerun: stable course and lesson IDs are upserted.
begin;
update public.academy_lessons set status='archived',archived_at=coalesce(archived_at,now()),updated_at=now() where status='published';
insert into public.academy_courses(id,language_id,level_id,title,slug,description,status,sort_order,estimated_hours)
select x.id,x.language_id,x.level_id,x.title,x.slug,x.description,x.status,x.sort_order,x.estimated_hours
from jsonb_to_recordset($courses$[{"id":"html","language_id":"html","level_id":"beginner","title":"HTML مقدماتی","slug":"html-course","description":"ساختار صفحات وب را از پایه یاد بگیر.","status":"published","sort_order":1,"estimated_hours":18},{"id":"html-intermediate","language_id":"html","level_id":"intermediate","title":"HTML متوسط","slug":"html-intermediate-course","description":"فرم‌های کامل، ساختار معنایی، رسانه و دسترس‌پذیری.","status":"published","sort_order":2,"estimated_hours":22},{"id":"html-advanced","language_id":"html","level_id":"advanced","title":"HTML پیشرفته","slug":"html-advanced-course","description":"استانداردهای مدرن، دسترس‌پذیری عمیق و معماری صفحات.","status":"published","sort_order":3,"estimated_hours":26},{"id":"css","language_id":"css","level_id":"beginner","title":"CSS مقدماتی","slug":"css-course","description":"رنگ، تایپوگرافی، مدل جعبه‌ای و چیدمان پایه.","status":"published","sort_order":1,"estimated_hours":18},{"id":"css-intermediate","language_id":"css","level_id":"intermediate","title":"CSS متوسط","slug":"css-intermediate-course","description":"Flexbox و Grid، واکنش‌گرایی، فرم و حرکت.","status":"published","sort_order":2,"estimated_hours":22},{"id":"css-advanced","language_id":"css","level_id":"advanced","title":"CSS پیشرفته","slug":"css-advanced-course","description":"معماری CSS، طراحی سیستم و بهینه‌سازی رابط.","status":"published","sort_order":3,"estimated_hours":26},{"id":"javascript","language_id":"javascript","level_id":"beginner","title":"JavaScript مقدماتی","slug":"javascript-course","description":"مبانی زبان، داده، شرط، حلقه، تابع و DOM.","status":"published","sort_order":1,"estimated_hours":18},{"id":"javascript-intermediate","language_id":"javascript","level_id":"intermediate","title":"JavaScript متوسط","slug":"javascript-intermediate-course","description":"DOM، رویداد، آرایه، فرم و ماژول.","status":"published","sort_order":2,"estimated_hours":22},{"id":"javascript-advanced","language_id":"javascript","level_id":"advanced","title":"JavaScript پیشرفته","slug":"javascript-advanced-course","description":"ناهمگامی، API، معماری، امنیت و تست.","status":"published","sort_order":3,"estimated_hours":26}]$courses$::jsonb)
as x(id text,language_id text,level_id text,title text,slug text,description text,status text,sort_order integer,estimated_hours numeric)
on conflict(language_id,level_id) do update set title=excluded.title,slug=excluded.slug,description=excluded.description,status='published',sort_order=excluded.sort_order,estimated_hours=excluded.estimated_hours,updated_at=now();
insert into public.academy_lessons(id,course_id,title,slug,summary,content_html,starter_code,exercise,status,sort_order,estimated_minutes)
select x.id,c.id,x.title,x.slug,x.summary,x.content_html,x.starter_code,x.exercise,x.status,x.sort_order,x.estimated_minutes
from jsonb_to_recordset($lessons$[{"id":"curriculum-324-html-01","course_id":"html","title":"HTML چیست و مرورگر چگونه آن را می‌خواند","slug":"html-beginner-01","summary":"در این درس HTML چیست و مرورگر چگونه آن را می‌خواند را به‌صورت عملی یاد می‌گیری. HTML زبان نشانه‌گذاری برای توصیف ساختار و معنای محتوای صفحه است؛ زبان برنامه‌نویسی برای محاسبه و تصمیم‌گیری نیست. مرورگر تگ‌ها را تحلیل می‌کند و از آن‌ها درختی از عناصر می‌سازد.","content_html":"<h3>هدف درس</h3><p>HTML زبان نشانه‌گذاری برای توصیف ساختار و معنای محتوای صفحه است؛ زبان برنامه‌نویسی برای محاسبه و تصمیم‌گیری نیست. مرورگر تگ‌ها را تحلیل می‌کند و از آن‌ها درختی از عناصر می‌سازد.</p><h3>نمونه و بررسی</h3><p>کد زیر را در فایل HTML خود قرار بده، ذخیره کن و نتیجه را در مرورگر ببین. سپس هر بخش را تغییر بده و اثر آن را بررسی کن.</p><pre><code>&lt;h1&gt;آکادمی NEXORA FORGE&lt;/h1&gt;\n&lt;p&gt;اینجا یاد می‌گیریم وب‌سایت چگونه ساخته می‌شود.&lt;/p&gt;</code></pre><h3>تمرین</h3><p>یک صفحه معرفی شخصی با یک عنوان اصلی و دو پاراگراف بساز. در توضیح خود بنویس HTML چه چیزی را مشخص می‌کند و چه کاری را به CSS می‌سپارد.</p><h3>نکته مهم</h3><p>اشتباه رایج: تصور اینکه HTML به‌تنهایی ظاهر نهایی و رفتار تعاملی را کنترل می‌کند.</p><h3>معیار موفقیت</h3><ul><li>کد بدون خطای ساختاری نوشته شده باشد.</li><li>بتوانی کاربرد عنصرها و ویژگی‌های استفاده‌شده را با زبان خودت توضیح بدهی.</li><li>تمرین را مستقل از نمونه کامل کنی.</li></ul>","starter_code":"<h1>آکادمی NEXORA FORGE</h1>\n<p>اینجا یاد می‌گیریم وب‌سایت چگونه ساخته می‌شود.</p>","exercise":"یک صفحه معرفی شخصی با یک عنوان اصلی و دو پاراگراف بساز. در توضیح خود بنویس HTML چه چیزی را مشخص می‌کند و چه کاری را به CSS می‌سپارد.","status":"published","sort_order":1,"estimated_minutes":20},{"id":"curriculum-324-html-02","course_id":"html","title":"ساخت اولین فایل HTML","slug":"html-beginner-02","summary":"در این درس ساخت اولین فایل HTML را به‌صورت عملی یاد می‌گیری. یک فایل متنی با پسوند .html بساز و آن را با مرورگر باز کن. مرورگر فایل را تفسیر می‌کند؛ لازم نیست برای یک صفحه ساده سرور نصب کنی.","content_html":"<h3>هدف درس</h3><p>یک فایل متنی با پسوند .html بساز و آن را با مرورگر باز کن. مرورگر فایل را تفسیر می‌کند؛ لازم نیست برای یک صفحه ساده سرور نصب کنی.</p><h3>نمونه و بررسی</h3><p>کد زیر را در فایل HTML خود قرار بده، ذخیره کن و نتیجه را در مرورگر ببین. سپس هر بخش را تغییر بده و اثر آن را بررسی کن.</p><pre><code>&lt;!doctype html&gt;\n&lt;html lang=\"fa\" dir=\"rtl\"&gt;\n  &lt;head&gt;&lt;meta charset=\"UTF-8\"&gt;&lt;title&gt;اولین صفحه&lt;/title&gt;&lt;/head&gt;\n  &lt;body&gt;&lt;h1&gt;سلام وب!&lt;/h1&gt;&lt;/body&gt;\n&lt;/html&gt;</code></pre><h3>تمرین</h3><p>فایلی به نام index.html بساز، کد را وارد کن، ذخیره کن و با مرورگر بازش کن. عنوان تب مرورگر را هم تغییر بده.</p><h3>نکته مهم</h3><p>اگر تغییرات دیده نمی‌شوند، فایل را ذخیره و صفحه را تازه‌سازی کن.</p><h3>معیار موفقیت</h3><ul><li>کد بدون خطای ساختاری نوشته شده باشد.</li><li>بتوانی کاربرد عنصرها و ویژگی‌های استفاده‌شده را با زبان خودت توضیح بدهی.</li><li>تمرین را مستقل از نمونه کامل کنی.</li></ul>","starter_code":"<!doctype html>\n<html lang=\"fa\" dir=\"rtl\">\n  <head><meta charset=\"UTF-8\"><title>اولین صفحه</title></head>\n  <body><h1>سلام وب!</h1></body>\n</html>","exercise":"فایلی به نام index.html بساز، کد را وارد کن، ذخیره کن و با مرورگر بازش کن. عنوان تب مرورگر را هم تغییر بده.","status":"published","sort_order":2,"estimated_minutes":25},{"id":"curriculum-324-html-03","course_id":"html","title":"ساختار استاندارد سند","slug":"html-beginner-03","summary":"در این درس ساختار استاندارد سند را به‌صورت عملی یاد می‌گیری. DOCTYPE حالت استاندارد HTML را فعال می‌کند. عنصر html ریشه سند است؛ head اطلاعات و تنظیمات سند را نگه می‌دارد و body محتوای قابل مشاهده را در بر می‌گیرد.","content_html":"<h3>هدف درس</h3><p>DOCTYPE حالت استاندارد HTML را فعال می‌کند. عنصر html ریشه سند است؛ head اطلاعات و تنظیمات سند را نگه می‌دارد و body محتوای قابل مشاهده را در بر می‌گیرد.</p><h3>نمونه و بررسی</h3><p>کد زیر را در فایل HTML خود قرار بده، ذخیره کن و نتیجه را در مرورگر ببین. سپس هر بخش را تغییر بده و اثر آن را بررسی کن.</p><pre><code>&lt;!doctype html&gt;\n&lt;html lang=\"fa\" dir=\"rtl\"&gt;\n&lt;head&gt;\n  &lt;meta charset=\"UTF-8\"&gt;\n  &lt;title&gt;ساختار سند&lt;/title&gt;\n&lt;/head&gt;\n&lt;body&gt;\n  &lt;main&gt;&lt;h1&gt;صفحه اصلی&lt;/h1&gt;&lt;/main&gt;\n&lt;/body&gt;\n&lt;/html&gt;</code></pre><h3>تمرین</h3><p>یک سند کامل بساز و جایگاه doctype، html، head و body را مشخص کن. سپس یک main به بدنه اضافه کن.</p><h3>نکته مهم</h3><p>محتوای قابل مشاهده را داخل head قرار نده.</p><h3>معیار موفقیت</h3><ul><li>کد بدون خطای ساختاری نوشته شده باشد.</li><li>بتوانی کاربرد عنصرها و ویژگی‌های استفاده‌شده را با زبان خودت توضیح بدهی.</li><li>تمرین را مستقل از نمونه کامل کنی.</li></ul>","starter_code":"<!doctype html>\n<html lang=\"fa\" dir=\"rtl\">\n<head>\n  <meta charset=\"UTF-8\">\n  <title>ساختار سند</title>\n</head>\n<body>\n  <main><h1>صفحه اصلی</h1></main>\n</body>\n</html>","exercise":"یک سند کامل بساز و جایگاه doctype، html، head و body را مشخص کن. سپس یک main به بدنه اضافه کن.","status":"published","sort_order":3,"estimated_minutes":30},{"id":"curriculum-324-html-04","course_id":"html","title":"زبان صفحه و جهت نوشتار","slug":"html-beginner-04","summary":"در این درس زبان صفحه و جهت نوشتار را به‌صورت عملی یاد می‌گیری. ویژگی lang زبان اصلی محتوا را اعلام می‌کند و dir جهت متن را تعیین می‌کند. این اطلاعات به مرورگر، صفحه‌خوان و ابزارهای ترجمه کمک می‌کنند.","content_html":"<h3>هدف درس</h3><p>ویژگی lang زبان اصلی محتوا را اعلام می‌کند و dir جهت متن را تعیین می‌کند. این اطلاعات به مرورگر، صفحه‌خوان و ابزارهای ترجمه کمک می‌کنند.</p><h3>نمونه و بررسی</h3><p>کد زیر را در فایل HTML خود قرار بده، ذخیره کن و نتیجه را در مرورگر ببین. سپس هر بخش را تغییر بده و اثر آن را بررسی کن.</p><pre><code>&lt;html lang=\"fa\" dir=\"rtl\"&gt;\n&lt;head&gt;&lt;meta charset=\"UTF-8\"&gt;&lt;title&gt;متن فارسی&lt;/title&gt;&lt;/head&gt;\n&lt;body&gt;&lt;p&gt;این صفحه فارسی و راست‌چین است.&lt;/p&gt;&lt;/body&gt;\n&lt;/html&gt;</code></pre><h3>تمرین</h3><p>یک صفحه فارسی بساز و lang را fa و dir را rtl قرار بده. در یک بخش کوتاه انگلیسی، جهت را فقط برای همان بخش ltr کن.</p><h3>نکته مهم</h3><p>جهت کل صفحه را با فاصله یا کاراکترهای ساختگی اصلاح نکن؛ از ویژگی dir استفاده کن.</p><h3>معیار موفقیت</h3><ul><li>کد بدون خطای ساختاری نوشته شده باشد.</li><li>بتوانی کاربرد عنصرها و ویژگی‌های استفاده‌شده را با زبان خودت توضیح بدهی.</li><li>تمرین را مستقل از نمونه کامل کنی.</li></ul>","starter_code":"<html lang=\"fa\" dir=\"rtl\">\n<head><meta charset=\"UTF-8\"><title>متن فارسی</title></head>\n<body><p>این صفحه فارسی و راست‌چین است.</p></body>\n</html>","exercise":"یک صفحه فارسی بساز و lang را fa و dir را rtl قرار بده. در یک بخش کوتاه انگلیسی، جهت را فقط برای همان بخش ltr کن.","status":"published","sort_order":4,"estimated_minutes":35},{"id":"curriculum-324-html-05","course_id":"html","title":"عنوان صفحه و اطلاعات head","slug":"html-beginner-05","summary":"در این درس عنوان صفحه و اطلاعات head را به‌صورت عملی یاد می‌گیری. عنصر title نام سند را در تب مرورگر و نتایج جست‌وجو نمایش می‌دهد. meta charset رمزگذاری نویسه‌ها را مشخص می‌کند تا حروف فارسی خراب نشوند.","content_html":"<h3>هدف درس</h3><p>عنصر title نام سند را در تب مرورگر و نتایج جست‌وجو نمایش می‌دهد. meta charset رمزگذاری نویسه‌ها را مشخص می‌کند تا حروف فارسی خراب نشوند.</p><h3>نمونه و بررسی</h3><p>کد زیر را در فایل HTML خود قرار بده، ذخیره کن و نتیجه را در مرورگر ببین. سپس هر بخش را تغییر بده و اثر آن را بررسی کن.</p><pre><code>&lt;head&gt;\n  &lt;meta charset=\"UTF-8\"&gt;\n  &lt;meta name=\"description\" content=\"آموزش رایگان HTML به زبان فارسی\"&gt;\n  &lt;title&gt;آموزش HTML | NEXORA FORGE&lt;/title&gt;\n&lt;/head&gt;</code></pre><h3>تمرین</h3><p>برای یک صفحه آموزش HTML عنوانی دقیق و توضیح meta description کوتاه بنویس. صفحه را باز کن و عنوان تب را بررسی کن.</p><h3>نکته مهم</h3><p>title را خالی نگذار و برای هر صفحه عنوان مرتبط و متمایز انتخاب کن.</p><h3>معیار موفقیت</h3><ul><li>کد بدون خطای ساختاری نوشته شده باشد.</li><li>بتوانی کاربرد عنصرها و ویژگی‌های استفاده‌شده را با زبان خودت توضیح بدهی.</li><li>تمرین را مستقل از نمونه کامل کنی.</li></ul>","starter_code":"<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"description\" content=\"آموزش رایگان HTML به زبان فارسی\">\n  <title>آموزش HTML | NEXORA FORGE</title>\n</head>","exercise":"برای یک صفحه آموزش HTML عنوانی دقیق و توضیح meta description کوتاه بنویس. صفحه را باز کن و عنوان تب را بررسی کن.","status":"published","sort_order":5,"estimated_minutes":20},{"id":"curriculum-324-html-06","course_id":"html","title":"عنصر، تگ و ویژگی","slug":"html-beginner-06","summary":"در این درس عنصر، تگ و ویژگی را به‌صورت عملی یاد می‌گیری. تگ نشانه متنی مانند h1 است؛ عنصر معمولاً از تگ آغاز، محتوا و تگ پایان تشکیل می‌شود. ویژگی‌ها اطلاعات یا تنظیمات بیشتری به عنصر می‌دهند.","content_html":"<h3>هدف درس</h3><p>تگ نشانه متنی مانند h1 است؛ عنصر معمولاً از تگ آغاز، محتوا و تگ پایان تشکیل می‌شود. ویژگی‌ها اطلاعات یا تنظیمات بیشتری به عنصر می‌دهند.</p><h3>نمونه و بررسی</h3><p>کد زیر را در فایل HTML خود قرار بده، ذخیره کن و نتیجه را در مرورگر ببین. سپس هر بخش را تغییر بده و اثر آن را بررسی کن.</p><pre><code>&lt;a href=\"https://example.com\" target=\"_blank\" rel=\"noopener\"&gt;باز کردن نمونه&lt;/a&gt;</code></pre><h3>تمرین</h3><p>یک پیوند بساز و href آن را به نشانی دلخواه تغییر بده. نام ویژگی و مقدار آن را از هم تشخیص بده.</p><h3>نکته مهم</h3><p>نام ویژگی را بدون مقدار لازم یا با کوتیشن ناقص ننویس.</p><h3>معیار موفقیت</h3><ul><li>کد بدون خطای ساختاری نوشته شده باشد.</li><li>بتوانی کاربرد عنصرها و ویژگی‌های استفاده‌شده را با زبان خودت توضیح بدهی.</li><li>تمرین را مستقل از نمونه کامل کنی.</li></ul>","starter_code":"<a href=\"https://example.com\" target=\"_blank\" rel=\"noopener\">باز کردن نمونه</a>","exercise":"یک پیوند بساز و href آن را به نشانی دلخواه تغییر بده. نام ویژگی و مقدار آن را از هم تشخیص بده.","status":"published","sort_order":6,"estimated_minutes":25},{"id":"curriculum-324-html-07","course_id":"html","title":"تیترها از h1 تا h6","slug":"html-beginner-07","summary":"در این درس تیترها از h1 تا h6 را به‌صورت عملی یاد می‌گیری. تیترها ساختار سلسله‌مراتبی محتوا را نشان می‌دهند. h1 عنوان اصلی صفحه و h2 و h3 زیرعنوان بخش‌ها هستند؛ اندازه ظاهری معیار انتخاب نیست.","content_html":"<h3>هدف درس</h3><p>تیترها ساختار سلسله‌مراتبی محتوا را نشان می‌دهند. h1 عنوان اصلی صفحه و h2 و h3 زیرعنوان بخش‌ها هستند؛ اندازه ظاهری معیار انتخاب نیست.</p><h3>نمونه و بررسی</h3><p>کد زیر را در فایل HTML خود قرار بده، ذخیره کن و نتیجه را در مرورگر ببین. سپس هر بخش را تغییر بده و اثر آن را بررسی کن.</p><pre><code>&lt;h1&gt;راهنمای HTML&lt;/h1&gt;\n&lt;h2&gt;ساختار سند&lt;/h2&gt;\n&lt;h3&gt;بخش head&lt;/h3&gt;\n&lt;h2&gt;متن و پیوندها&lt;/h2&gt;</code></pre><h3>تمرین</h3><p>برای مقاله‌ای با سه بخش، یک h1 و چند h2 و h3 منطقی بساز. ترتیب را بر اساس ساختار موضوع انتخاب کن.</p><h3>نکته مهم</h3><p>از تیترها فقط برای بزرگ‌کردن متن استفاده نکن و سطح‌ها را بی‌دلیل نپر.</p><h3>معیار موفقیت</h3><ul><li>کد بدون خطای ساختاری نوشته شده باشد.</li><li>بتوانی کاربرد عنصرها و ویژگی‌های استفاده‌شده را با زبان خودت توضیح بدهی.</li><li>تمرین را مستقل از نمونه کامل کنی.</li></ul>","starter_code":"<h1>راهنمای HTML</h1>\n<h2>ساختار سند</h2>\n<h3>بخش head</h3>\n<h2>متن و پیوندها</h2>","exercise":"برای مقاله‌ای با سه بخش، یک h1 و چند h2 و h3 منطقی بساز. ترتیب را بر اساس ساختار موضوع انتخاب کن.","status":"published","sort_order":7,"estimated_minutes":30},{"id":"curriculum-324-html-08","course_id":"html","title":"پاراگراف و شکست خط","slug":"html-beginner-08","summary":"در این درس پاراگراف و شکست خط را به‌صورت عملی یاد می‌گیری. p برای یک بند مستقل متن است. br فقط وقتی مناسب است که شکست خط بخشی از معنا باشد؛ برای فاصله‌گذاری بین بخش‌ها از آن استفاده نکن.","content_html":"<h3>هدف درس</h3><p>p برای یک بند مستقل متن است. br فقط وقتی مناسب است که شکست خط بخشی از معنا باشد؛ برای فاصله‌گذاری بین بخش‌ها از آن استفاده نکن.</p><h3>نمونه و بررسی</h3><p>کد زیر را در فایل HTML خود قرار بده، ذخیره کن و نتیجه را در مرورگر ببین. سپس هر بخش را تغییر بده و اثر آن را بررسی کن.</p><pre><code>&lt;p&gt;HTML ساختار محتوا را مشخص می‌کند.&lt;/p&gt;\n&lt;p&gt;CSS ظاهر صفحه را کنترل می‌کند.&lt;/p&gt;\n&lt;p&gt;نشانی ما:&lt;br&gt;هرات، افغانستان&lt;/p&gt;</code></pre><h3>تمرین</h3><p>سه پاراگراف مستقل بنویس و فقط در یک نشانی یا شعر از br استفاده کن. تفاوت آن‌ها را توضیح بده.</p><h3>نکته مهم</h3><p>برای ایجاد فاصله عمودی چندین br پشت سر هم قرار نده.</p><h3>معیار موفقیت</h3><ul><li>کد بدون خطای ساختاری نوشته شده باشد.</li><li>بتوانی کاربرد عنصرها و ویژگی‌های استفاده‌شده را با زبان خودت توضیح بدهی.</li><li>تمرین را مستقل از نمونه کامل کنی.</li></ul>","starter_code":"<p>HTML ساختار محتوا را مشخص می‌کند.</p>\n<p>CSS ظاهر صفحه را کنترل می‌کند.</p>\n<p>نشانی ما:<br>هرات، افغانستان</p>","exercise":"سه پاراگراف مستقل بنویس و فقط در یک نشانی یا شعر از br استفاده کن. تفاوت آن‌ها را توضیح بده.","status":"published","sort_order":8,"estimated_minutes":35},{"id":"curriculum-324-html-09","course_id":"html","title":"تأکید معنایی با strong و em","slug":"html-beginner-09","summary":"در این درس تأکید معنایی با strong و em را به‌صورت عملی یاد می‌گیری. strong اهمیت زیاد و em تأکید گفتاری را منتقل می‌کند. این عناصر معنایی‌اند؛ صرفاً ابزار ضخیم یا مورب کردن متن نیستند.","content_html":"<h3>هدف درس</h3><p>strong اهمیت زیاد و em تأکید گفتاری را منتقل می‌کند. این عناصر معنایی‌اند؛ صرفاً ابزار ضخیم یا مورب کردن متن نیستند.</p><h3>نمونه و بررسی</h3><p>کد زیر را در فایل HTML خود قرار بده، ذخیره کن و نتیجه را در مرورگر ببین. سپس هر بخش را تغییر بده و اثر آن را بررسی کن.</p><pre><code>&lt;p&gt;&lt;strong&gt;هشدار:&lt;/strong&gt; پیش از بستن صفحه فایل را ذخیره کن.&lt;/p&gt;\n&lt;p&gt;این نکته &lt;em&gt;بسیار مهم&lt;/em&gt; است.&lt;/p&gt;</code></pre><h3>تمرین</h3><p>یک راهنمای کوتاه بنویس و در آن یک هشدار مهم و یک واژه با تأکید معنایی قرار بده.</p><h3>نکته مهم</h3><p>برای ظاهر صرف از CSS استفاده کن، نه اینکه معنای متن را با strong عوض کنی.</p><h3>معیار موفقیت</h3><ul><li>کد بدون خطای ساختاری نوشته شده باشد.</li><li>بتوانی کاربرد عنصرها و ویژگی‌های استفاده‌شده را با زبان خودت توضیح بدهی.</li><li>تمرین را مستقل از نمونه کامل کنی.</li></ul>","starter_code":"<p><strong>هشدار:</strong> پیش از بستن صفحه فایل را ذخیره کن.</p>\n<p>این نکته <em>بسیار مهم</em> است.</p>","exercise":"یک راهنمای کوتاه بنویس و در آن یک هشدار مهم و یک واژه با تأکید معنایی قرار بده.","status":"published","sort_order":9,"estimated_minutes":20},{"id":"curriculum-324-html-10","course_id":"html","title":"پیوند به صفحه دیگر","slug":"html-beginner-10","summary":"در این درس پیوند به صفحه دیگر را به‌صورت عملی یاد می‌گیری. عنصر a با href پیوند می‌سازد. متن پیوند باید مقصد را برای کاربر روشن کند؛ عباراتی مثل «اینجا کلیک کن» اطلاعات کمی می‌دهند.","content_html":"<h3>هدف درس</h3><p>عنصر a با href پیوند می‌سازد. متن پیوند باید مقصد را برای کاربر روشن کند؛ عباراتی مثل «اینجا کلیک کن» اطلاعات کمی می‌دهند.</p><h3>نمونه و بررسی</h3><p>کد زیر را در فایل HTML خود قرار بده، ذخیره کن و نتیجه را در مرورگر ببین. سپس هر بخش را تغییر بده و اثر آن را بررسی کن.</p><pre><code>&lt;a href=\"about.html\"&gt;درباره آکادمی&lt;/a&gt;\n&lt;a href=\"https://developer.mozilla.org/\"&gt;مرجع MDN&lt;/a&gt;</code></pre><h3>تمرین</h3><p>دو فایل index.html و about.html بساز و بین آن‌ها پیوند نسبی برقرار کن. یک پیوند خارجی هم اضافه کن.</p><h3>نکته مهم</h3><p>برای پیوند داخلی نام و مسیر فایل را دقیق وارد کن.</p><h3>معیار موفقیت</h3><ul><li>کد بدون خطای ساختاری نوشته شده باشد.</li><li>بتوانی کاربرد عنصرها و ویژگی‌های استفاده‌شده را با زبان خودت توضیح بدهی.</li><li>تمرین را مستقل از نمونه کامل کنی.</li></ul>","starter_code":"<a href=\"about.html\">درباره آکادمی</a>\n<a href=\"https://developer.mozilla.org/\">مرجع MDN</a>","exercise":"دو فایل index.html و about.html بساز و بین آن‌ها پیوند نسبی برقرار کن. یک پیوند خارجی هم اضافه کن.","status":"published","sort_order":10,"estimated_minutes":25},{"id":"curriculum-324-html-11","course_id":"html","title":"پیوند ایمیل و تلفن","slug":"html-beginner-11","summary":"در این درس پیوند ایمیل و تلفن را به‌صورت عملی یاد می‌گیری. طرح‌های mailto و tel در href می‌توانند برنامه ایمیل یا تماس دستگاه را باز کنند. عملکرد آن‌ها به دستگاه و برنامه‌های نصب‌شده وابسته است.","content_html":"<h3>هدف درس</h3><p>طرح‌های mailto و tel در href می‌توانند برنامه ایمیل یا تماس دستگاه را باز کنند. عملکرد آن‌ها به دستگاه و برنامه‌های نصب‌شده وابسته است.</p><h3>نمونه و بررسی</h3><p>کد زیر را در فایل HTML خود قرار بده، ذخیره کن و نتیجه را در مرورگر ببین. سپس هر بخش را تغییر بده و اثر آن را بررسی کن.</p><pre><code>&lt;a href=\"mailto:hello@example.com\"&gt;ارسال ایمیل&lt;/a&gt;\n&lt;a href=\"tel:+93700000000\"&gt;تماس با ما&lt;/a&gt;</code></pre><h3>تمرین</h3><p>در صفحه تماس، پیوند ایمیل و تلفن بساز. از شماره و ایمیل آزمایشی استفاده کن و بدان که کلیک روی آن‌ها چه می‌کند.</p><h3>نکته مهم</h3><p>این پیوندها ارسال خودکار انجام نمی‌دهند؛ برنامه مناسب دستگاه را باز می‌کنند.</p><h3>معیار موفقیت</h3><ul><li>کد بدون خطای ساختاری نوشته شده باشد.</li><li>بتوانی کاربرد عنصرها و ویژگی‌های استفاده‌شده را با زبان خودت توضیح بدهی.</li><li>تمرین را مستقل از نمونه کامل کنی.</li></ul>","starter_code":"<a href=\"mailto:hello@example.com\">ارسال ایمیل</a>\n<a href=\"tel:+93700000000\">تماس با ما</a>","exercise":"در صفحه تماس، پیوند ایمیل و تلفن بساز. از شماره و ایمیل آزمایشی استفاده کن و بدان که کلیک روی آن‌ها چه می‌کند.","status":"published","sort_order":11,"estimated_minutes":30},{"id":"curriculum-324-html-12","course_id":"html","title":"تصویر و ویژگی src","slug":"html-beginner-12","summary":"در این درس تصویر و ویژگی src را به‌صورت عملی یاد می‌گیری. عنصر img تصویر را در صفحه قرار می‌دهد. src مسیر فایل تصویر و alt جایگزین متنی آن است. img عنصر تهی است و تگ پایان ندارد.","content_html":"<h3>هدف درس</h3><p>عنصر img تصویر را در صفحه قرار می‌دهد. src مسیر فایل تصویر و alt جایگزین متنی آن است. img عنصر تهی است و تگ پایان ندارد.</p><h3>نمونه و بررسی</h3><p>کد زیر را در فایل HTML خود قرار بده، ذخیره کن و نتیجه را در مرورگر ببین. سپس هر بخش را تغییر بده و اثر آن را بررسی کن.</p><pre><code>&lt;img src=\"images/workshop.jpg\" alt=\"دانش‌آموز در حال تمرین کدنویسی\" width=\"640\"&gt;</code></pre><h3>تمرین</h3><p>یک پوشه images بساز، تصویر مجاز خودت را در آن قرار بده و مسیر src را درست تنظیم کن. صفحه را در مرورگر بررسی کن.</p><h3>نکته مهم</h3><p>مسیر نسبی را نسبت به محل فایل HTML حساب کن.</p><h3>معیار موفقیت</h3><ul><li>کد بدون خطای ساختاری نوشته شده باشد.</li><li>بتوانی کاربرد عنصرها و ویژگی‌های استفاده‌شده را با زبان خودت توضیح بدهی.</li><li>تمرین را مستقل از نمونه کامل کنی.</li></ul>","starter_code":"<img src=\"images/workshop.jpg\" alt=\"دانش‌آموز در حال تمرین کدنویسی\" width=\"640\">","exercise":"یک پوشه images بساز، تصویر مجاز خودت را در آن قرار بده و مسیر src را درست تنظیم کن. صفحه را در مرورگر بررسی کن.","status":"published","sort_order":12,"estimated_minutes":35},{"id":"curriculum-324-html-13","course_id":"html","title":"متن جایگزین تصویر","slug":"html-beginner-13","summary":"در این درس متن جایگزین تصویر را به‌صورت عملی یاد می‌گیری. alt باید هدف یا محتوای مهم تصویر را منتقل کند. تصویر تزئینی معمولاً alt خالی دارد؛ نوشتن نام فایل یا عبارت «عکس» کمک چندانی نمی‌کند.","content_html":"<h3>هدف درس</h3><p>alt باید هدف یا محتوای مهم تصویر را منتقل کند. تصویر تزئینی معمولاً alt خالی دارد؛ نوشتن نام فایل یا عبارت «عکس» کمک چندانی نمی‌کند.</p><h3>نمونه و بررسی</h3><p>کد زیر را در فایل HTML خود قرار بده، ذخیره کن و نتیجه را در مرورگر ببین. سپس هر بخش را تغییر بده و اثر آن را بررسی کن.</p><pre><code>&lt;img src=\"logo.svg\" alt=\"نشان NEXORA FORGE\"&gt;\n&lt;img src=\"divider.png\" alt=\"\"&gt;</code></pre><h3>تمرین</h3><p>برای یک تصویر آموزشی، یک عکس تزئینی و یک نمودار، alt مناسب بنویس. برای نمودار، اطلاعات ضروری را در متن صفحه هم شرح بده.</p><h3>نکته مهم</h3><p>alt خالی برای تصویر اطلاعاتی مناسب نیست؛ متن جایگزین باید متناسب با کاربرد تصویر باشد.</p><h3>معیار موفقیت</h3><ul><li>کد بدون خطای ساختاری نوشته شده باشد.</li><li>بتوانی کاربرد عنصرها و ویژگی‌های استفاده‌شده را با زبان خودت توضیح بدهی.</li><li>تمرین را مستقل از نمونه کامل کنی.</li></ul>","starter_code":"<img src=\"logo.svg\" alt=\"نشان NEXORA FORGE\">\n<img src=\"divider.png\" alt=\"\">","exercise":"برای یک تصویر آموزشی، یک عکس تزئینی و یک نمودار، alt مناسب بنویس. برای نمودار، اطلاعات ضروری را در متن صفحه هم شرح بده.","status":"published","sort_order":13,"estimated_minutes":20},{"id":"curriculum-324-html-14","course_id":"html","title":"فهرست نامرتب ul","slug":"html-beginner-14","summary":"در این درس فهرست نامرتب ul را به‌صورت عملی یاد می‌گیری. ul برای مجموعه‌ای است که ترتیب آیتم‌هایش اهمیت ندارد. هر گزینه باید داخل li قرار گیرد؛ ظاهر نشانه‌گذاری را CSS تغییر می‌دهد.","content_html":"<h3>هدف درس</h3><p>ul برای مجموعه‌ای است که ترتیب آیتم‌هایش اهمیت ندارد. هر گزینه باید داخل li قرار گیرد؛ ظاهر نشانه‌گذاری را CSS تغییر می‌دهد.</p><h3>نمونه و بررسی</h3><p>کد زیر را در فایل HTML خود قرار بده، ذخیره کن و نتیجه را در مرورگر ببین. سپس هر بخش را تغییر بده و اثر آن را بررسی کن.</p><pre><code>&lt;h2&gt;ابزارهای موردنیاز&lt;/h2&gt;\n&lt;ul&gt;&lt;li&gt;ویرایشگر کد&lt;/li&gt;&lt;li&gt;مرورگر&lt;/li&gt;&lt;li&gt;تمرین روزانه&lt;/li&gt;&lt;/ul&gt;</code></pre><h3>تمرین</h3><p>فهرست پنج ابزار یا موضوع موردنیاز برای یادگیری وب بساز و مطمئن شو هر مورد li است.</p><h3>نکته مهم</h3><p>متن آیتم‌ها را مستقیم و بدون li داخل ul قرار نده.</p><h3>معیار موفقیت</h3><ul><li>کد بدون خطای ساختاری نوشته شده باشد.</li><li>بتوانی کاربرد عنصرها و ویژگی‌های استفاده‌شده را با زبان خودت توضیح بدهی.</li><li>تمرین را مستقل از نمونه کامل کنی.</li></ul>","starter_code":"<h2>ابزارهای موردنیاز</h2>\n<ul><li>ویرایشگر کد</li><li>مرورگر</li><li>تمرین روزانه</li></ul>","exercise":"فهرست پنج ابزار یا موضوع موردنیاز برای یادگیری وب بساز و مطمئن شو هر مورد li است.","status":"published","sort_order":14,"estimated_minutes":25},{"id":"curriculum-324-html-15","course_id":"html","title":"فهرست مرتب ol","slug":"html-beginner-15","summary":"در این درس فهرست مرتب ol را به‌صورت عملی یاد می‌گیری. ol برای مراحل یا مواردی است که ترتیب آن‌ها مهم است. مرورگر شماره‌گذاری را مدیریت می‌کند و با ویژگی start می‌توان شماره شروع را تعیین کرد.","content_html":"<h3>هدف درس</h3><p>ol برای مراحل یا مواردی است که ترتیب آن‌ها مهم است. مرورگر شماره‌گذاری را مدیریت می‌کند و با ویژگی start می‌توان شماره شروع را تعیین کرد.</p><h3>نمونه و بررسی</h3><p>کد زیر را در فایل HTML خود قرار بده، ذخیره کن و نتیجه را در مرورگر ببین. سپس هر بخش را تغییر بده و اثر آن را بررسی کن.</p><pre><code>&lt;ol&gt;\n  &lt;li&gt;فایل را بساز.&lt;/li&gt;\n  &lt;li&gt;کد HTML را بنویس.&lt;/li&gt;\n  &lt;li&gt;در مرورگر آزمایش کن.&lt;/li&gt;\n&lt;/ol&gt;</code></pre><h3>تمرین</h3><p>مراحل انتشار یک صفحه ساده را با ol بنویس. ترتیب را عوض کن و تفاوت خروجی را مشاهده کن.</p><h3>نکته مهم</h3><p>اگر ترتیب مراحل مهم نیست، ul انتخاب مناسب‌تری است.</p><h3>معیار موفقیت</h3><ul><li>کد بدون خطای ساختاری نوشته شده باشد.</li><li>بتوانی کاربرد عنصرها و ویژگی‌های استفاده‌شده را با زبان خودت توضیح بدهی.</li><li>تمرین را مستقل از نمونه کامل کنی.</li></ul>","starter_code":"<ol>\n  <li>فایل را بساز.</li>\n  <li>کد HTML را بنویس.</li>\n  <li>در مرورگر آزمایش کن.</li>\n</ol>","exercise":"مراحل انتشار یک صفحه ساده را با ol بنویس. ترتیب را عوض کن و تفاوت خروجی را مشاهده کن.","status":"published","sort_order":15,"estimated_minutes":30},{"id":"curriculum-324-html-16","course_id":"html","title":"فهرست تو در تو","slug":"html-beginner-16","summary":"در این درس فهرست تو در تو را به‌صورت عملی یاد می‌گیری. می‌توان یک فهرست را داخل li فهرست دیگر قرار داد تا رابطه گروه و زیرگروه روشن شود. فهرست تو در تو باید از نظر ساختاری داخل یک آیتم باشد.","content_html":"<h3>هدف درس</h3><p>می‌توان یک فهرست را داخل li فهرست دیگر قرار داد تا رابطه گروه و زیرگروه روشن شود. فهرست تو در تو باید از نظر ساختاری داخل یک آیتم باشد.</p><h3>نمونه و بررسی</h3><p>کد زیر را در فایل HTML خود قرار بده، ذخیره کن و نتیجه را در مرورگر ببین. سپس هر بخش را تغییر بده و اثر آن را بررسی کن.</p><pre><code>&lt;ul&gt;\n  &lt;li&gt;Front-end\n    &lt;ul&gt;&lt;li&gt;HTML&lt;/li&gt;&lt;li&gt;CSS&lt;/li&gt;&lt;li&gt;JavaScript&lt;/li&gt;&lt;/ul&gt;\n  &lt;/li&gt;\n  &lt;li&gt;Back-end&lt;/li&gt;\n&lt;/ul&gt;</code></pre><h3>تمرین</h3><p>یک نقشه یادگیری وب با دو گروه و حداقل دو زیرموضوع برای هر گروه بساز.</p><h3>نکته مهم</h3><p>فهرست فرزند را داخل li والد قرار بده، نه به‌صورت هم‌سطح و نامرتبط.</p><h3>معیار موفقیت</h3><ul><li>کد بدون خطای ساختاری نوشته شده باشد.</li><li>بتوانی کاربرد عنصرها و ویژگی‌های استفاده‌شده را با زبان خودت توضیح بدهی.</li><li>تمرین را مستقل از نمونه کامل کنی.</li></ul>","starter_code":"<ul>\n  <li>Front-end\n    <ul><li>HTML</li><li>CSS</li><li>JavaScript</li></ul>\n  </li>\n  <li>Back-end</li>\n</ul>","exercise":"یک نقشه یادگیری وب با دو گروه و حداقل دو زیرموضوع برای هر گروه بساز.","status":"published","sort_order":16,"estimated_minutes":35},{"id":"curriculum-324-html-17","course_id":"html","title":"معنای div و span","slug":"html-beginner-17","summary":"در این درس معنای div و span را به‌صورت عملی یاد می‌گیری. div ظرف عمومی بلوکی و span ظرف عمومی درون‌خطی است. وقتی عنصر معنایی مناسب‌تری وجود ندارد، از آن‌ها برای گروه‌بندی و هدف‌گذاری CSS استفاده کن.","content_html":"<h3>هدف درس</h3><p>div ظرف عمومی بلوکی و span ظرف عمومی درون‌خطی است. وقتی عنصر معنایی مناسب‌تری وجود ندارد، از آن‌ها برای گروه‌بندی و هدف‌گذاری CSS استفاده کن.</p><h3>نمونه و بررسی</h3><p>کد زیر را در فایل HTML خود قرار بده، ذخیره کن و نتیجه را در مرورگر ببین. سپس هر بخش را تغییر بده و اثر آن را بررسی کن.</p><pre><code>&lt;div class=\"card\"&gt;\n  &lt;h2&gt;دوره HTML&lt;/h2&gt;\n  &lt;p&gt;سطح: &lt;span class=\"level\"&gt;مقدماتی&lt;/span&gt;&lt;/p&gt;\n&lt;/div&gt;</code></pre><h3>تمرین</h3><p>یک کارت معرفی دوره بساز و از div برای گروه‌بندی و span برای مشخص‌کردن یک عبارت درون متن استفاده کن.</p><h3>نکته مهم</h3><p>برای header، nav، main یا article از div عمومی استفاده نکن، اگر عنصر معنایی دقیق‌تر مناسب است.</p><h3>معیار موفقیت</h3><ul><li>کد بدون خطای ساختاری نوشته شده باشد.</li><li>بتوانی کاربرد عنصرها و ویژگی‌های استفاده‌شده را با زبان خودت توضیح بدهی.</li><li>تمرین را مستقل از نمونه کامل کنی.</li></ul>","starter_code":"<div class=\"card\">\n  <h2>دوره HTML</h2>\n  <p>سطح: <span class=\"level\">مقدماتی</span></p>\n</div>","exercise":"یک کارت معرفی دوره بساز و از div برای گروه‌بندی و span برای مشخص‌کردن یک عبارت درون متن استفاده کن.","status":"published","sort_order":17,"estimated_minutes":20},{"id":"curriculum-324-html-18","course_id":"html","title":"ساختار معنایی header و footer","slug":"html-beginner-18","summary":"در این درس ساختار معنایی header و footer را به‌صورت عملی یاد می‌گیری. header محتوای مقدماتی یک صفحه یا بخش را گروه‌بندی می‌کند و footer اطلاعات پایانی همان محدوده را نگه می‌دارد. این عناصر جایگاه معنایی دارند، نه صرفاً ظاهر ثابت.","content_html":"<h3>هدف درس</h3><p>header محتوای مقدماتی یک صفحه یا بخش را گروه‌بندی می‌کند و footer اطلاعات پایانی همان محدوده را نگه می‌دارد. این عناصر جایگاه معنایی دارند، نه صرفاً ظاهر ثابت.</p><h3>نمونه و بررسی</h3><p>کد زیر را در فایل HTML خود قرار بده، ذخیره کن و نتیجه را در مرورگر ببین. سپس هر بخش را تغییر بده و اثر آن را بررسی کن.</p><pre><code>&lt;header&gt;&lt;h1&gt;آکادمی وب&lt;/h1&gt;&lt;p&gt;مسیر یادگیری&lt;/p&gt;&lt;/header&gt;\n&lt;main&gt;&lt;p&gt;محتوای اصلی&lt;/p&gt;&lt;/main&gt;\n&lt;footer&gt;&lt;p&gt;© 2026 NEXORA FORGE&lt;/p&gt;&lt;/footer&gt;</code></pre><h3>تمرین</h3><p>صفحه معرفی دوره را با header و footer بساز و مشخص کن هرکدام چه اطلاعاتی دارند.</p><h3>نکته مهم</h3><p>header را الزاماً فقط یک‌بار در کل سند به کار نبر؛ می‌تواند متعلق به بخش یا مقاله هم باشد.</p><h3>معیار موفقیت</h3><ul><li>کد بدون خطای ساختاری نوشته شده باشد.</li><li>بتوانی کاربرد عنصرها و ویژگی‌های استفاده‌شده را با زبان خودت توضیح بدهی.</li><li>تمرین را مستقل از نمونه کامل کنی.</li></ul>","starter_code":"<header><h1>آکادمی وب</h1><p>مسیر یادگیری</p></header>\n<main><p>محتوای اصلی</p></main>\n<footer><p>© 2026 NEXORA FORGE</p></footer>","exercise":"صفحه معرفی دوره را با header و footer بساز و مشخص کن هرکدام چه اطلاعاتی دارند.","status":"published","sort_order":18,"estimated_minutes":25},{"id":"curriculum-324-html-19","course_id":"html","title":"ناوبری با nav","slug":"html-beginner-19","summary":"در این درس ناوبری با nav را به‌صورت عملی یاد می‌گیری. nav بخش مهمی از پیوندهای ناوبری صفحه یا سایت را مشخص می‌کند. همه پیوندها لازم نیست داخل nav باشند؛ فقط مجموعه‌های اصلی ناوبری را گروه‌بندی کن.","content_html":"<h3>هدف درس</h3><p>nav بخش مهمی از پیوندهای ناوبری صفحه یا سایت را مشخص می‌کند. همه پیوندها لازم نیست داخل nav باشند؛ فقط مجموعه‌های اصلی ناوبری را گروه‌بندی کن.</p><h3>نمونه و بررسی</h3><p>کد زیر را در فایل HTML خود قرار بده، ذخیره کن و نتیجه را در مرورگر ببین. سپس هر بخش را تغییر بده و اثر آن را بررسی کن.</p><pre><code>&lt;nav aria-label=\"ناوبری اصلی\"&gt;\n  &lt;ul&gt;&lt;li&gt;&lt;a href=\"index.html\"&gt;خانه&lt;/a&gt;&lt;/li&gt;&lt;li&gt;&lt;a href=\"courses.html\"&gt;دوره‌ها&lt;/a&gt;&lt;/li&gt;&lt;/ul&gt;\n&lt;/nav&gt;</code></pre><h3>تمرین</h3><p>یک نوار ناوبری با سه مقصد بساز و برای آن نام قابل فهم تعیین کن.</p><h3>نکته مهم</h3><p>nav را برای هر پیوند پراکنده یا لینک پاورقی بی‌دلیل استفاده نکن.</p><h3>معیار موفقیت</h3><ul><li>کد بدون خطای ساختاری نوشته شده باشد.</li><li>بتوانی کاربرد عنصرها و ویژگی‌های استفاده‌شده را با زبان خودت توضیح بدهی.</li><li>تمرین را مستقل از نمونه کامل کنی.</li></ul>","starter_code":"<nav aria-label=\"ناوبری اصلی\">\n  <ul><li><a href=\"index.html\">خانه</a></li><li><a href=\"courses.html\">دوره‌ها</a></li></ul>\n</nav>","exercise":"یک نوار ناوبری با سه مقصد بساز و برای آن نام قابل فهم تعیین کن.","status":"published","sort_order":19,"estimated_minutes":30},{"id":"curriculum-324-html-20","course_id":"html","title":"محتوای اصلی با main و article","slug":"html-beginner-20","summary":"در این درس محتوای اصلی با main و article را به‌صورت عملی یاد می‌گیری. main محتوای غالب و منحصربه‌فرد صفحه را مشخص می‌کند و معمولاً در هر سند یک نمونه قابل مشاهده دارد. article محتوایی مستقل و قابل بازنشر را نمایش می‌دهد.","content_html":"<h3>هدف درس</h3><p>main محتوای غالب و منحصربه‌فرد صفحه را مشخص می‌کند و معمولاً در هر سند یک نمونه قابل مشاهده دارد. article محتوایی مستقل و قابل بازنشر را نمایش می‌دهد.</p><h3>نمونه و بررسی</h3><p>کد زیر را در فایل HTML خود قرار بده، ذخیره کن و نتیجه را در مرورگر ببین. سپس هر بخش را تغییر بده و اثر آن را بررسی کن.</p><pre><code>&lt;main&gt;\n  &lt;article&gt;&lt;h1&gt;چرا HTML مهم است؟&lt;/h1&gt;&lt;p&gt;ساختار محتوا را توصیف می‌کند.&lt;/p&gt;&lt;/article&gt;\n&lt;/main&gt;</code></pre><h3>تمرین</h3><p>یک صفحه وبلاگ با main و دو article مستقل طراحی کن. عنوان هر مقاله را داخل همان article قرار بده.</p><h3>نکته مهم</h3><p>main را برای محتوای تکراری مانند منوی ثابت سایت به کار نبر.</p><h3>معیار موفقیت</h3><ul><li>کد بدون خطای ساختاری نوشته شده باشد.</li><li>بتوانی کاربرد عنصرها و ویژگی‌های استفاده‌شده را با زبان خودت توضیح بدهی.</li><li>تمرین را مستقل از نمونه کامل کنی.</li></ul>","starter_code":"<main>\n  <article><h1>چرا HTML مهم است؟</h1><p>ساختار محتوا را توصیف می‌کند.</p></article>\n</main>","exercise":"یک صفحه وبلاگ با main و دو article مستقل طراحی کن. عنوان هر مقاله را داخل همان article قرار بده.","status":"published","sort_order":20,"estimated_minutes":35},{"id":"curriculum-324-html-21","course_id":"html","title":"بخش‌بندی با section و aside","slug":"html-beginner-21","summary":"در این درس بخش‌بندی با section و aside را به‌صورت عملی یاد می‌گیری. section یک بخش موضوعی با عنوان است. aside محتوای جانبی مرتبط را مشخص می‌کند. انتخاب عنصر باید بر اساس نقش محتوا باشد، نه صرفاً شکل ظاهری.","content_html":"<h3>هدف درس</h3><p>section یک بخش موضوعی با عنوان است. aside محتوای جانبی مرتبط را مشخص می‌کند. انتخاب عنصر باید بر اساس نقش محتوا باشد، نه صرفاً شکل ظاهری.</p><h3>نمونه و بررسی</h3><p>کد زیر را در فایل HTML خود قرار بده، ذخیره کن و نتیجه را در مرورگر ببین. سپس هر بخش را تغییر بده و اثر آن را بررسی کن.</p><pre><code>&lt;main&gt;\n  &lt;section&gt;&lt;h2&gt;سرفصل دوره&lt;/h2&gt;&lt;p&gt;HTML پایه...&lt;/p&gt;&lt;/section&gt;\n  &lt;aside&gt;&lt;h2&gt;نکته&lt;/h2&gt;&lt;p&gt;تمرین روزانه را فراموش نکن.&lt;/p&gt;&lt;/aside&gt;\n&lt;/main&gt;</code></pre><h3>تمرین</h3><p>صفحه دوره‌ای بساز که دو section عنوان‌دار و یک aside شامل نکته جانبی داشته باشد.</p><h3>نکته مهم</h3><p>هر div را به‌زور section نکن؛ بخش موضوعی معمولاً باید عنوان یا مفهوم مشخص داشته باشد.</p><h3>معیار موفقیت</h3><ul><li>کد بدون خطای ساختاری نوشته شده باشد.</li><li>بتوانی کاربرد عنصرها و ویژگی‌های استفاده‌شده را با زبان خودت توضیح بدهی.</li><li>تمرین را مستقل از نمونه کامل کنی.</li></ul>","starter_code":"<main>\n  <section><h2>سرفصل دوره</h2><p>HTML پایه...</p></section>\n  <aside><h2>نکته</h2><p>تمرین روزانه را فراموش نکن.</p></aside>\n</main>","exercise":"صفحه دوره‌ای بساز که دو section عنوان‌دار و یک aside شامل نکته جانبی داشته باشد.","status":"published","sort_order":21,"estimated_minutes":20},{"id":"curriculum-324-html-22","course_id":"html","title":"ویژگی‌های عمومی id و class","slug":"html-beginner-22","summary":"در این درس ویژگی‌های عمومی id و class را به‌صورت عملی یاد می‌گیری. id شناسه یکتا در یک سند است و class برای گروهی از عناصر قابل تکرار استفاده می‌شود. این ویژگی‌ها در CSS و JavaScript برای یافتن عناصر کاربرد دارند.","content_html":"<h3>هدف درس</h3><p>id شناسه یکتا در یک سند است و class برای گروهی از عناصر قابل تکرار استفاده می‌شود. این ویژگی‌ها در CSS و JavaScript برای یافتن عناصر کاربرد دارند.</p><h3>نمونه و بررسی</h3><p>کد زیر را در فایل HTML خود قرار بده، ذخیره کن و نتیجه را در مرورگر ببین. سپس هر بخش را تغییر بده و اثر آن را بررسی کن.</p><pre><code>&lt;h2 id=\"requirements\"&gt;پیش‌نیازها&lt;/h2&gt;\n&lt;p class=\"muted\"&gt;آشنایی با کار با فایل‌ها کافی است.&lt;/p&gt;\n&lt;p class=\"muted\"&gt;مرورگر به‌روز داشته باش.&lt;/p&gt;</code></pre><h3>تمرین</h3><p>برای یک عنوان id یکتا و برای دو پاراگراف class مشترک تعیین کن. در کل صفحه id تکراری نداشته باش.</p><h3>نکته مهم</h3><p>class می‌تواند تکرار شود؛ id در همان سند باید یکتا باشد.</p><h3>معیار موفقیت</h3><ul><li>کد بدون خطای ساختاری نوشته شده باشد.</li><li>بتوانی کاربرد عنصرها و ویژگی‌های استفاده‌شده را با زبان خودت توضیح بدهی.</li><li>تمرین را مستقل از نمونه کامل کنی.</li></ul>","starter_code":"<h2 id=\"requirements\">پیش‌نیازها</h2>\n<p class=\"muted\">آشنایی با کار با فایل‌ها کافی است.</p>\n<p class=\"muted\">مرورگر به‌روز داشته باش.</p>","exercise":"برای یک عنوان id یکتا و برای دو پاراگراف class مشترک تعیین کن. در کل صفحه id تکراری نداشته باش.","status":"published","sort_order":22,"estimated_minutes":25},{"id":"curriculum-324-html-23","course_id":"html","title":"ویژگی‌های data-*","slug":"html-beginner-23","summary":"در این درس ویژگی‌های data-* را به‌صورت عملی یاد می‌گیری. ویژگی‌های data-* داده سفارشی متنی را به عنصر متصل می‌کنند. JavaScript می‌تواند آن‌ها را از dataset بخواند؛ داده حساس را در HTML قرار نده.","content_html":"<h3>هدف درس</h3><p>ویژگی‌های data-* داده سفارشی متنی را به عنصر متصل می‌کنند. JavaScript می‌تواند آن‌ها را از dataset بخواند؛ داده حساس را در HTML قرار نده.</p><h3>نمونه و بررسی</h3><p>کد زیر را در فایل HTML خود قرار بده، ذخیره کن و نتیجه را در مرورگر ببین. سپس هر بخش را تغییر بده و اثر آن را بررسی کن.</p><pre><code>&lt;button type=\"button\" data-course=\"html\"&gt;مشاهده دوره HTML&lt;/button&gt;\n&lt;p data-level=\"beginner\"&gt;سطح مقدماتی&lt;/p&gt;</code></pre><h3>تمرین</h3><p>به سه کارت دوره ویژگی data-course اضافه کن و مقدار هرکدام را متفاوت قرار بده. با ابزار توسعه مرورگر مقدارها را ببین.</p><h3>نکته مهم</h3><p>data-* جایگزین پایگاه داده یا محل نگهداری رمز و اطلاعات خصوصی نیست.</p><h3>معیار موفقیت</h3><ul><li>کد بدون خطای ساختاری نوشته شده باشد.</li><li>بتوانی کاربرد عنصرها و ویژگی‌های استفاده‌شده را با زبان خودت توضیح بدهی.</li><li>تمرین را مستقل از نمونه کامل کنی.</li></ul>","starter_code":"<button type=\"button\" data-course=\"html\">مشاهده دوره HTML</button>\n<p data-level=\"beginner\">سطح مقدماتی</p>","exercise":"به سه کارت دوره ویژگی data-course اضافه کن و مقدار هرکدام را متفاوت قرار بده. با ابزار توسعه مرورگر مقدارها را ببین.","status":"published","sort_order":23,"estimated_minutes":30},{"id":"curriculum-324-html-24","course_id":"html","title":"جدول و ساختار پایه","slug":"html-beginner-24","summary":"در این درس جدول و ساختار پایه را به‌صورت عملی یاد می‌گیری. table داده‌های رابطه‌ای را در ردیف و ستون نمایش می‌دهد. tr ردیف، th سلول عنوان و td سلول داده است؛ برای چیدمان صفحه از جدول استفاده نکن.","content_html":"<h3>هدف درس</h3><p>table داده‌های رابطه‌ای را در ردیف و ستون نمایش می‌دهد. tr ردیف، th سلول عنوان و td سلول داده است؛ برای چیدمان صفحه از جدول استفاده نکن.</p><h3>نمونه و بررسی</h3><p>کد زیر را در فایل HTML خود قرار بده، ذخیره کن و نتیجه را در مرورگر ببین. سپس هر بخش را تغییر بده و اثر آن را بررسی کن.</p><pre><code>&lt;table&gt;\n  &lt;tr&gt;&lt;th&gt;درس&lt;/th&gt;&lt;th&gt;زمان&lt;/th&gt;&lt;/tr&gt;\n  &lt;tr&gt;&lt;td&gt;HTML&lt;/td&gt;&lt;td&gt;۳۰ دقیقه&lt;/td&gt;&lt;/tr&gt;\n&lt;/table&gt;</code></pre><h3>تمرین</h3><p>جدول برنامه هفتگی با سه ستون روز، موضوع و زمان و دست‌کم سه ردیف داده بساز.</p><h3>نکته مهم</h3><p>برای چیدمان عمومی صفحه از table استفاده نکن؛ جدول مخصوص داده جدولی است.</p><h3>معیار موفقیت</h3><ul><li>کد بدون خطای ساختاری نوشته شده باشد.</li><li>بتوانی کاربرد عنصرها و ویژگی‌های استفاده‌شده را با زبان خودت توضیح بدهی.</li><li>تمرین را مستقل از نمونه کامل کنی.</li></ul>","starter_code":"<table>\n  <tr><th>درس</th><th>زمان</th></tr>\n  <tr><td>HTML</td><td>۳۰ دقیقه</td></tr>\n</table>","exercise":"جدول برنامه هفتگی با سه ستون روز، موضوع و زمان و دست‌کم سه ردیف داده بساز.","status":"published","sort_order":24,"estimated_minutes":35},{"id":"curriculum-324-html-25","course_id":"html","title":"عنوان جدول با caption و thead و tbody","slug":"html-beginner-25","summary":"در این درس عنوان جدول با caption و thead و tbody را به‌صورت عملی یاد می‌گیری. caption عنوان جدول را معرفی می‌کند. thead سرستون‌ها و tbody ردیف‌های داده را گروه‌بندی می‌کنند و به فهم ساختار کمک می‌کنند.","content_html":"<h3>هدف درس</h3><p>caption عنوان جدول را معرفی می‌کند. thead سرستون‌ها و tbody ردیف‌های داده را گروه‌بندی می‌کنند و به فهم ساختار کمک می‌کنند.</p><h3>نمونه و بررسی</h3><p>کد زیر را در فایل HTML خود قرار بده، ذخیره کن و نتیجه را در مرورگر ببین. سپس هر بخش را تغییر بده و اثر آن را بررسی کن.</p><pre><code>&lt;table&gt;\n  &lt;caption&gt;برنامه دوره‌ها&lt;/caption&gt;\n  &lt;thead&gt;&lt;tr&gt;&lt;th scope=\"col\"&gt;دوره&lt;/th&gt;&lt;th scope=\"col\"&gt;سطح&lt;/th&gt;&lt;/tr&gt;&lt;/thead&gt;\n  &lt;tbody&gt;&lt;tr&gt;&lt;td&gt;HTML&lt;/td&gt;&lt;td&gt;مقدماتی&lt;/td&gt;&lt;/tr&gt;&lt;/tbody&gt;\n&lt;/table&gt;</code></pre><h3>تمرین</h3><p>جدول برنامه درسی را با caption، thead و tbody بازنویسی کن و برای سرستون‌ها scope=\"col\" بگذار.</p><h3>نکته مهم</h3><p>عنوان جدول را با یک تیتر بیرون جدول اشتباه نگیر؛ caption بخشی از جدول است.</p><h3>معیار موفقیت</h3><ul><li>کد بدون خطای ساختاری نوشته شده باشد.</li><li>بتوانی کاربرد عنصرها و ویژگی‌های استفاده‌شده را با زبان خودت توضیح بدهی.</li><li>تمرین را مستقل از نمونه کامل کنی.</li></ul>","starter_code":"<table>\n  <caption>برنامه دوره‌ها</caption>\n  <thead><tr><th scope=\"col\">دوره</th><th scope=\"col\">سطح</th></tr></thead>\n  <tbody><tr><td>HTML</td><td>مقدماتی</td></tr></tbody>\n</table>","exercise":"جدول برنامه درسی را با caption، thead و tbody بازنویسی کن و برای سرستون‌ها scope=\"col\" بگذار.","status":"published","sort_order":25,"estimated_minutes":20},{"id":"curriculum-324-html-26","course_id":"html","title":"فرم و عنصر form","slug":"html-beginner-26","summary":"در این درس فرم و عنصر form را به‌صورت عملی یاد می‌گیری. form مجموعه‌ای از کنترل‌ها را برای دریافت و ارسال داده گروه‌بندی می‌کند. action مقصد ارسال و method روش ارسال را تعیین می‌کند؛ پردازش واقعی به سمت سرور نیاز دارد.","content_html":"<h3>هدف درس</h3><p>form مجموعه‌ای از کنترل‌ها را برای دریافت و ارسال داده گروه‌بندی می‌کند. action مقصد ارسال و method روش ارسال را تعیین می‌کند؛ پردازش واقعی به سمت سرور نیاز دارد.</p><h3>نمونه و بررسی</h3><p>کد زیر را در فایل HTML خود قرار بده، ذخیره کن و نتیجه را در مرورگر ببین. سپس هر بخش را تغییر بده و اثر آن را بررسی کن.</p><pre><code>&lt;form action=\"/register\" method=\"post\"&gt;\n  &lt;label for=\"student-name\"&gt;نام&lt;/label&gt;\n  &lt;input id=\"student-name\" name=\"name\" type=\"text\"&gt;\n  &lt;button type=\"submit\"&gt;ارسال&lt;/button&gt;\n&lt;/form&gt;</code></pre><h3>تمرین</h3><p>یک فرم ثبت‌نام آزمایشی بساز و برای ورودی name تعیین کن. توضیح بده چرا وجود فرم به‌تنهایی ذخیره‌سازی اطلاعات را انجام نمی‌دهد.</p><h3>نکته مهم</h3><p>اطلاعات حساس را با فرم آزمایشی به مقصد ناشناس ارسال نکن.</p><h3>معیار موفقیت</h3><ul><li>کد بدون خطای ساختاری نوشته شده باشد.</li><li>بتوانی کاربرد عنصرها و ویژگی‌های استفاده‌شده را با زبان خودت توضیح بدهی.</li><li>تمرین را مستقل از نمونه کامل کنی.</li></ul>","starter_code":"<form action=\"/register\" method=\"post\">\n  <label for=\"student-name\">نام</label>\n  <input id=\"student-name\" name=\"name\" type=\"text\">\n  <button type=\"submit\">ارسال</button>\n</form>","exercise":"یک فرم ثبت‌نام آزمایشی بساز و برای ورودی name تعیین کن. توضیح بده چرا وجود فرم به‌تنهایی ذخیره‌سازی اطلاعات را انجام نمی‌دهد.","status":"published","sort_order":26,"estimated_minutes":25},{"id":"curriculum-324-html-27","course_id":"html","title":"label و ارتباط با ورودی","slug":"html-beginner-27","summary":"در این درس label و ارتباط با ورودی را به‌صورت عملی یاد می‌گیری. label نام قابل فهم کنترل را مشخص می‌کند. اتصال for در label به id ورودی باعث می‌شود کلیک روی برچسب نیز کنترل را فعال کند و صفحه‌خوان نام آن را بخواند.","content_html":"<h3>هدف درس</h3><p>label نام قابل فهم کنترل را مشخص می‌کند. اتصال for در label به id ورودی باعث می‌شود کلیک روی برچسب نیز کنترل را فعال کند و صفحه‌خوان نام آن را بخواند.</p><h3>نمونه و بررسی</h3><p>کد زیر را در فایل HTML خود قرار بده، ذخیره کن و نتیجه را در مرورگر ببین. سپس هر بخش را تغییر بده و اثر آن را بررسی کن.</p><pre><code>&lt;label for=\"email\"&gt;ایمیل&lt;/label&gt;\n&lt;input id=\"email\" name=\"email\" type=\"email\"&gt;</code></pre><h3>تمرین</h3><p>برای نام، ایمیل و رمز سه ورودی بساز و هرکدام را با label دارای for و id متناظر متصل کن.</p><h3>نکته مهم</h3><p>placeholder جایگزین label نیست؛ پس از واردکردن متن، placeholder ناپدید می‌شود.</p><h3>معیار موفقیت</h3><ul><li>کد بدون خطای ساختاری نوشته شده باشد.</li><li>بتوانی کاربرد عنصرها و ویژگی‌های استفاده‌شده را با زبان خودت توضیح بدهی.</li><li>تمرین را مستقل از نمونه کامل کنی.</li></ul>","starter_code":"<label for=\"email\">ایمیل</label>\n<input id=\"email\" name=\"email\" type=\"email\">","exercise":"برای نام، ایمیل و رمز سه ورودی بساز و هرکدام را با label دارای for و id متناظر متصل کن.","status":"published","sort_order":27,"estimated_minutes":30},{"id":"curriculum-324-html-28","course_id":"html","title":"انواع ورودی input","slug":"html-beginner-28","summary":"در این درس انواع ورودی input را به‌صورت عملی یاد می‌گیری. نوع input رفتار و صفحه‌کلید مناسب را تعیین می‌کند؛ مانند email، password، number، date و checkbox. انتخاب نوع درست اعتبارسنجی اولیه و تجربه کاربری را بهتر می‌کند.","content_html":"<h3>هدف درس</h3><p>نوع input رفتار و صفحه‌کلید مناسب را تعیین می‌کند؛ مانند email، password، number، date و checkbox. انتخاب نوع درست اعتبارسنجی اولیه و تجربه کاربری را بهتر می‌کند.</p><h3>نمونه و بررسی</h3><p>کد زیر را در فایل HTML خود قرار بده، ذخیره کن و نتیجه را در مرورگر ببین. سپس هر بخش را تغییر بده و اثر آن را بررسی کن.</p><pre><code>&lt;label for=\"age\"&gt;سن&lt;/label&gt;&lt;input id=\"age\" name=\"age\" type=\"number\" min=\"10\" max=\"99\"&gt;\n&lt;label&gt;&lt;input type=\"checkbox\" name=\"agree\"&gt; قوانین را می‌پذیرم&lt;/label&gt;</code></pre><h3>تمرین</h3><p>فرمی با ورودی تاریخ تولد، ایمیل، عدد و checkbox بساز. برای هرکدام نوع مناسب انتخاب کن.</p><h3>نکته مهم</h3><p>اعتبارسنجی مرورگر جای بررسی امن داده در سرور را نمی‌گیرد.</p><h3>معیار موفقیت</h3><ul><li>کد بدون خطای ساختاری نوشته شده باشد.</li><li>بتوانی کاربرد عنصرها و ویژگی‌های استفاده‌شده را با زبان خودت توضیح بدهی.</li><li>تمرین را مستقل از نمونه کامل کنی.</li></ul>","starter_code":"<label for=\"age\">سن</label><input id=\"age\" name=\"age\" type=\"number\" min=\"10\" max=\"99\">\n<label><input type=\"checkbox\" name=\"agree\"> قوانین را می‌پذیرم</label>","exercise":"فرمی با ورودی تاریخ تولد، ایمیل، عدد و checkbox بساز. برای هرکدام نوع مناسب انتخاب کن.","status":"published","sort_order":28,"estimated_minutes":35},{"id":"curriculum-324-html-29","course_id":"html","title":"ویژگی‌های required و minlength","slug":"html-beginner-29","summary":"در این درس ویژگی‌های required و minlength را به‌صورت عملی یاد می‌گیری. required ورود مقدار را الزامی می‌کند و minlength حداقل طول متن را مشخص می‌کند. مرورگر هنگام ارسال فرم اعتبارسنجی اولیه انجام می‌دهد.","content_html":"<h3>هدف درس</h3><p>required ورود مقدار را الزامی می‌کند و minlength حداقل طول متن را مشخص می‌کند. مرورگر هنگام ارسال فرم اعتبارسنجی اولیه انجام می‌دهد.</p><h3>نمونه و بررسی</h3><p>کد زیر را در فایل HTML خود قرار بده، ذخیره کن و نتیجه را در مرورگر ببین. سپس هر بخش را تغییر بده و اثر آن را بررسی کن.</p><pre><code>&lt;form&gt;\n  &lt;label for=\"user\"&gt;شناسه&lt;/label&gt;\n  &lt;input id=\"user\" name=\"user\" required minlength=\"4\"&gt;\n  &lt;button&gt;بررسی&lt;/button&gt;\n&lt;/form&gt;</code></pre><h3>تمرین</h3><p>فرم ساخت شناسه‌ای بساز که خالی نباشد و حداقل چهار نویسه داشته باشد. حالت خالی و مقدار کوتاه را آزمایش کن.</p><h3>نکته مهم</h3><p>این محدودیت‌ها به‌تنهایی امنیت یا اعتبار داده در سرور را تضمین نمی‌کنند.</p><h3>معیار موفقیت</h3><ul><li>کد بدون خطای ساختاری نوشته شده باشد.</li><li>بتوانی کاربرد عنصرها و ویژگی‌های استفاده‌شده را با زبان خودت توضیح بدهی.</li><li>تمرین را مستقل از نمونه کامل کنی.</li></ul>","starter_code":"<form>\n  <label for=\"user\">شناسه</label>\n  <input id=\"user\" name=\"user\" required minlength=\"4\">\n  <button>بررسی</button>\n</form>","exercise":"فرم ساخت شناسه‌ای بساز که خالی نباشد و حداقل چهار نویسه داشته باشد. حالت خالی و مقدار کوتاه را آزمایش کن.","status":"published","sort_order":29,"estimated_minutes":20},{"id":"curriculum-324-html-30","course_id":"html","title":"select و option","slug":"html-beginner-30","summary":"در این درس select و option را به‌صورت عملی یاد می‌گیری. select برای انتخاب از گزینه‌های از پیش تعریف‌شده مناسب است. هر option یک انتخاب و value مقدار ارسالی آن را تعیین می‌کند.","content_html":"<h3>هدف درس</h3><p>select برای انتخاب از گزینه‌های از پیش تعریف‌شده مناسب است. هر option یک انتخاب و value مقدار ارسالی آن را تعیین می‌کند.</p><h3>نمونه و بررسی</h3><p>کد زیر را در فایل HTML خود قرار بده، ذخیره کن و نتیجه را در مرورگر ببین. سپس هر بخش را تغییر بده و اثر آن را بررسی کن.</p><pre><code>&lt;label for=\"level\"&gt;سطح دوره&lt;/label&gt;\n&lt;select id=\"level\" name=\"level\"&gt;\n  &lt;option value=\"beginner\"&gt;مقدماتی&lt;/option&gt;\n  &lt;option value=\"intermediate\"&gt;متوسط&lt;/option&gt;\n  &lt;option value=\"advanced\"&gt;پیشرفته&lt;/option&gt;\n&lt;/select&gt;</code></pre><h3>تمرین</h3><p>یک انتخاب‌گر سطح دوره با سه گزینه بساز و value انگلیسی و متن نمایشی فارسی قرار بده.</p><h3>نکته مهم</h3><p>متن نمایشی و value می‌توانند متفاوت باشند؛ مقدار ارسالی را آگاهانه انتخاب کن.</p><h3>معیار موفقیت</h3><ul><li>کد بدون خطای ساختاری نوشته شده باشد.</li><li>بتوانی کاربرد عنصرها و ویژگی‌های استفاده‌شده را با زبان خودت توضیح بدهی.</li><li>تمرین را مستقل از نمونه کامل کنی.</li></ul>","starter_code":"<label for=\"level\">سطح دوره</label>\n<select id=\"level\" name=\"level\">\n  <option value=\"beginner\">مقدماتی</option>\n  <option value=\"intermediate\">متوسط</option>\n  <option value=\"advanced\">پیشرفته</option>\n</select>","exercise":"یک انتخاب‌گر سطح دوره با سه گزینه بساز و value انگلیسی و متن نمایشی فارسی قرار بده.","status":"published","sort_order":30,"estimated_minutes":25},{"id":"curriculum-324-html-31","course_id":"html","title":"textarea برای متن چندخطی","slug":"html-beginner-31","summary":"در این درس textarea برای متن چندخطی را به‌صورت عملی یاد می‌گیری. textarea ورودی متن چندخطی است. برخلاف input، متن آن بین تگ آغاز و پایان قرار می‌گیرد و می‌توان اندازه اولیه را با rows و cols تعیین کرد.","content_html":"<h3>هدف درس</h3><p>textarea ورودی متن چندخطی است. برخلاف input، متن آن بین تگ آغاز و پایان قرار می‌گیرد و می‌توان اندازه اولیه را با rows و cols تعیین کرد.</p><h3>نمونه و بررسی</h3><p>کد زیر را در فایل HTML خود قرار بده، ذخیره کن و نتیجه را در مرورگر ببین. سپس هر بخش را تغییر بده و اثر آن را بررسی کن.</p><pre><code>&lt;label for=\"message\"&gt;پیام&lt;/label&gt;\n&lt;textarea id=\"message\" name=\"message\" rows=\"5\" maxlength=\"500\"&gt;&lt;/textarea&gt;</code></pre><h3>تمرین</h3><p>فرم بازخورد بساز که یک textarea با حداکثر ۵۰۰ نویسه داشته باشد. برچسب واضح برای آن بنویس.</p><h3>نکته مهم</h3><p>برای متن چندخطی از input type=text استفاده نکن.</p><h3>معیار موفقیت</h3><ul><li>کد بدون خطای ساختاری نوشته شده باشد.</li><li>بتوانی کاربرد عنصرها و ویژگی‌های استفاده‌شده را با زبان خودت توضیح بدهی.</li><li>تمرین را مستقل از نمونه کامل کنی.</li></ul>","starter_code":"<label for=\"message\">پیام</label>\n<textarea id=\"message\" name=\"message\" rows=\"5\" maxlength=\"500\"></textarea>","exercise":"فرم بازخورد بساز که یک textarea با حداکثر ۵۰۰ نویسه داشته باشد. برچسب واضح برای آن بنویس.","status":"published","sort_order":31,"estimated_minutes":30},{"id":"curriculum-324-html-32","course_id":"html","title":"button و نوع دکمه","slug":"html-beginner-32","summary":"در این درس button و نوع دکمه را به‌صورت عملی یاد می‌گیری. button می‌تواند submit، reset یا button باشد. داخل فرم، نوع پیش‌فرض ممکن است submit باشد؛ تعیین type رفتار را روشن و از ارسال ناخواسته جلوگیری می‌کند.","content_html":"<h3>هدف درس</h3><p>button می‌تواند submit، reset یا button باشد. داخل فرم، نوع پیش‌فرض ممکن است submit باشد؛ تعیین type رفتار را روشن و از ارسال ناخواسته جلوگیری می‌کند.</p><h3>نمونه و بررسی</h3><p>کد زیر را در فایل HTML خود قرار بده، ذخیره کن و نتیجه را در مرورگر ببین. سپس هر بخش را تغییر بده و اثر آن را بررسی کن.</p><pre><code>&lt;button type=\"button\"&gt;نمایش راهنما&lt;/button&gt;\n&lt;button type=\"submit\"&gt;ثبت فرم&lt;/button&gt;\n&lt;button type=\"reset\"&gt;پاک‌کردن فرم&lt;/button&gt;</code></pre><h3>تمرین</h3><p>در یک فرم سه دکمه با نوع‌های مشخص بساز و رفتار هرکدام را در مرورگر آزمایش کن.</p><h3>نکته مهم</h3><p>دکمه‌ای که فقط قرار است JavaScript را اجرا کند باید type=\"button\" داشته باشد.</p><h3>معیار موفقیت</h3><ul><li>کد بدون خطای ساختاری نوشته شده باشد.</li><li>بتوانی کاربرد عنصرها و ویژگی‌های استفاده‌شده را با زبان خودت توضیح بدهی.</li><li>تمرین را مستقل از نمونه کامل کنی.</li></ul>","starter_code":"<button type=\"button\">نمایش راهنما</button>\n<button type=\"submit\">ثبت فرم</button>\n<button type=\"reset\">پاک‌کردن فرم</button>","exercise":"در یک فرم سه دکمه با نوع‌های مشخص بساز و رفتار هرکدام را در مرورگر آزمایش کن.","status":"published","sort_order":32,"estimated_minutes":35},{"id":"curriculum-324-html-33","course_id":"html","title":"audio و video","slug":"html-beginner-33","summary":"در این درس audio و video را به‌صورت عملی یاد می‌گیری. audio و video رسانه را با کنترل‌های بومی مرورگر پخش می‌کنند. برای دسترس‌پذیری و سازگاری، در صورت نیاز چند source و متن جایگزین ارائه کن.","content_html":"<h3>هدف درس</h3><p>audio و video رسانه را با کنترل‌های بومی مرورگر پخش می‌کنند. برای دسترس‌پذیری و سازگاری، در صورت نیاز چند source و متن جایگزین ارائه کن.</p><h3>نمونه و بررسی</h3><p>کد زیر را در فایل HTML خود قرار بده، ذخیره کن و نتیجه را در مرورگر ببین. سپس هر بخش را تغییر بده و اثر آن را بررسی کن.</p><pre><code>&lt;video controls width=\"480\"&gt;\n  &lt;source src=\"intro.mp4\" type=\"video/mp4\"&gt;\n  مرورگر شما از ویدیو پشتیبانی نمی‌کند.\n&lt;/video&gt;</code></pre><h3>تمرین</h3><p>یک فایل رسانه‌ای مجاز در پوشه پروژه قرار بده و با video یا audio پخش کن. controls را فعال و مسیر را بررسی کن.</p><h3>نکته مهم</h3><p>فایل رسانه را بدون توجه به مجوز استفاده دیگران کپی نکن.</p><h3>معیار موفقیت</h3><ul><li>کد بدون خطای ساختاری نوشته شده باشد.</li><li>بتوانی کاربرد عنصرها و ویژگی‌های استفاده‌شده را با زبان خودت توضیح بدهی.</li><li>تمرین را مستقل از نمونه کامل کنی.</li></ul>","starter_code":"<video controls width=\"480\">\n  <source src=\"intro.mp4\" type=\"video/mp4\">\n  مرورگر شما از ویدیو پشتیبانی نمی‌کند.\n</video>","exercise":"یک فایل رسانه‌ای مجاز در پوشه پروژه قرار بده و با video یا audio پخش کن. controls را فعال و مسیر را بررسی کن.","status":"published","sort_order":33,"estimated_minutes":20},{"id":"curriculum-324-html-34","course_id":"html","title":"قرار دادن محتوای خارجی با iframe","slug":"html-beginner-34","summary":"در این درس قرار دادن محتوای خارجی با iframe را به‌صورت عملی یاد می‌گیری. iframe یک صفحه یا محتوای خارجی را در محدوده‌ای از صفحه جاسازی می‌کند. فقط منبع قابل اعتماد را وارد کن و برای آن title توصیفی بگذار.","content_html":"<h3>هدف درس</h3><p>iframe یک صفحه یا محتوای خارجی را در محدوده‌ای از صفحه جاسازی می‌کند. فقط منبع قابل اعتماد را وارد کن و برای آن title توصیفی بگذار.</p><h3>نمونه و بررسی</h3><p>کد زیر را در فایل HTML خود قرار بده، ذخیره کن و نتیجه را در مرورگر ببین. سپس هر بخش را تغییر بده و اثر آن را بررسی کن.</p><pre><code>&lt;iframe src=\"https://www.example.com\" title=\"صفحه نمونه\" width=\"600\" height=\"350\" loading=\"lazy\"&gt;&lt;/iframe&gt;</code></pre><h3>تمرین</h3><p>یک محتوای آزمایشی مجاز را با iframe جاسازی کن و title توصیفی اضافه کن. محدودیت‌های نمایش سایت‌های خارجی را بررسی کن.</p><h3>نکته مهم</h3><p>همه سایت‌ها اجازه جاسازی در iframe نمی‌دهند؛ این محدودیت را با دورزدن امنیتی حل نکن.</p><h3>معیار موفقیت</h3><ul><li>کد بدون خطای ساختاری نوشته شده باشد.</li><li>بتوانی کاربرد عنصرها و ویژگی‌های استفاده‌شده را با زبان خودت توضیح بدهی.</li><li>تمرین را مستقل از نمونه کامل کنی.</li></ul>","starter_code":"<iframe src=\"https://www.example.com\" title=\"صفحه نمونه\" width=\"600\" height=\"350\" loading=\"lazy\"></iframe>","exercise":"یک محتوای آزمایشی مجاز را با iframe جاسازی کن و title توصیفی اضافه کن. محدودیت‌های نمایش سایت‌های خارجی را بررسی کن.","status":"published","sort_order":34,"estimated_minutes":25},{"id":"curriculum-324-html-35","course_id":"html","title":"نشانه‌گذاری کد و نقل‌قول","slug":"html-beginner-35","summary":"در این درس نشانه‌گذاری کد و نقل‌قول را به‌صورت عملی یاد می‌گیری. code برای قطعه کد درون‌خطی و pre برای متن از پیش قالب‌بندی‌شده مناسب است. blockquote نقل‌قول بلند از منبع دیگر را مشخص می‌کند.","content_html":"<h3>هدف درس</h3><p>code برای قطعه کد درون‌خطی و pre برای متن از پیش قالب‌بندی‌شده مناسب است. blockquote نقل‌قول بلند از منبع دیگر را مشخص می‌کند.</p><h3>نمونه و بررسی</h3><p>کد زیر را در فایل HTML خود قرار بده، ذخیره کن و نتیجه را در مرورگر ببین. سپس هر بخش را تغییر بده و اثر آن را بررسی کن.</p><pre><code>&lt;p&gt;برای تیتر از &lt;code&gt;&amp;lt;h1&amp;gt;&lt;/code&gt; استفاده می‌کنیم.&lt;/p&gt;\n&lt;pre&gt;&lt;code&gt;const name = \"NEXORA\";\nconsole.log(name);&lt;/code&gt;&lt;/pre&gt;</code></pre><h3>تمرین</h3><p>در یک درس، یک تگ HTML را با code نمایش بده و یک نمونه چندخطی را داخل pre و code قرار بده.</p><h3>نکته مهم</h3><p>کد HTML را داخل نمونه با نویسه‌های &lt; و &gt; نمایش بده تا مرورگر آن را به‌عنوان تگ اجرا نکند.</p><h3>معیار موفقیت</h3><ul><li>کد بدون خطای ساختاری نوشته شده باشد.</li><li>بتوانی کاربرد عنصرها و ویژگی‌های استفاده‌شده را با زبان خودت توضیح بدهی.</li><li>تمرین را مستقل از نمونه کامل کنی.</li></ul>","starter_code":"<p>برای تیتر از <code>&lt;h1&gt;</code> استفاده می‌کنیم.</p>\n<pre><code>const name = \"NEXORA\";\nconsole.log(name);</code></pre>","exercise":"در یک درس، یک تگ HTML را با code نمایش بده و یک نمونه چندخطی را داخل pre و code قرار بده.","status":"published","sort_order":35,"estimated_minutes":30},{"id":"curriculum-324-html-36","course_id":"html","title":"پروژه پایانی: ساخت صفحه معرفی دانش‌آموز","slug":"html-beginner-36-final-project","summary":"در پروژه پایانی HTML مقدماتی، ساختار سند، عناصر معنایی، پیوندها، فهرست‌ها، تصویر، جدول و فرم را در یک صفحه واقعی ترکیب می‌کنی.","content_html":"<h3>هدف پروژه</h3><p>اکنون باید آموخته‌های HTML مقدماتی را در یک صفحه منسجم به کار ببری. این پروژه فقط تمرین نشانه‌گذاری است؛ هنوز CSS یا ذخیره‌سازی سمت سرور ندارد.</p><h3>ساختار مورد انتظار</h3><ul><li>سند کامل با doctype، lang، charset و viewport</li><li>header، nav، main، section و footer</li><li>تصویر دارای alt معنادار</li><li>فهرست مهارت‌ها و جدول دارای caption و سرستون</li><li>فرم دارای label، textarea و دکمه با type مشخص</li></ul><h3>نمونه شروع</h3><p>کد starter را در فایل index.html قرار بده. فایل تصویر را در همان پوشه بگذار یا مسیر src را متناسب با پروژه خودت تغییر بده.</p><h3>تمرین نهایی</h3><p>صفحه معرفی خودت را کامل کن. دست‌کم سه بخش ناوبری داشته باش، اطلاعات واقعی و غیرحساس وارد کن، مسیر پیوندها را آزمایش کن و همه عناصر را با معنای درست انتخاب کن.</p><h3>معیار ارزیابی</h3><ol><li>صفحه در موبایل و رایانه باز شود.</li><li>ساختار سند و ترتیب تیترها منطقی باشد.</li><li>تصویر alt مناسب داشته باشد.</li><li>هر ورودی فرم برچسب قابل مشاهده داشته باشد.</li><li>اعتبارسنج HTML خطاهای مهم را گزارش نکند.</li></ol><h3>محدودیت مهم</h3><p>فرم نمونه بدون backend اطلاعات را ذخیره یا ارسال واقعی نمی‌کند. این پروژه عمداً فقط HTML است؛ ظاهر حرفه‌ای در دوره CSS ساخته خواهد شد.</p>","starter_code":"<!doctype html>\n<html lang=\"fa\" dir=\"rtl\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <title>پروفایل دانش‌آموز</title>\n</head>\n<body>\n  <header>\n    <h1>پروفایل من</h1>\n    <nav aria-label=\"ناوبری اصلی\">\n      <a href=\"#about\">درباره من</a>\n      <a href=\"#skills\">مهارت‌ها</a>\n      <a href=\"#contact\">تماس</a>\n    </nav>\n  </header>\n  <main>\n    <section id=\"about\">\n      <h2>درباره من</h2>\n      <p>من در حال یادگیری طراحی وب هستم.</p>\n      <img src=\"profile.jpg\" alt=\"تصویر پروفایل دانش‌آموز\" width=\"180\">\n    </section>\n    <section id=\"skills\">\n      <h2>مهارت‌ها</h2>\n      <ul><li>HTML</li><li>حل مسئله</li></ul>\n      <table>\n        <caption>برنامه هفتگی</caption>\n        <thead><tr><th scope=\"col\">روز</th><th scope=\"col\">موضوع</th></tr></thead>\n        <tbody><tr><td>شنبه</td><td>HTML</td></tr></tbody>\n      </table>\n    </section>\n    <section id=\"contact\">\n      <h2>تماس</h2>\n      <form>\n        <label for=\"message\">پیام</label>\n        <textarea id=\"message\" name=\"message\" rows=\"4\"></textarea>\n        <button type=\"submit\">ارسال آزمایشی</button>\n      </form>\n    </section>\n  </main>\n  <footer><p>© NEXORA FORGE</p></footer>\n</body>\n</html>","exercise":"یک صفحه معرفی دانش‌آموز با header، nav، main، سه section، تصویر دارای alt، فهرست، جدول معنایی، فرم برچسب‌دار و footer بساز. آن را در مرورگر و اعتبارسنج HTML آزمایش کن و خطاها را اصلاح کن.","status":"published","sort_order":36,"estimated_minutes":60},{"id":"curriculum-324-html-intermediate-01","course_id":"html-intermediate","title":"fieldset و legend","slug":"html-intermediate-01","summary":"fieldset و legend: گروه‌بندی معنایی کنترل‌های مرتبط در فرم‌های بزرگ.","content_html":"<h3>هدف درس</h3><p>گروه‌بندی معنایی کنترل‌های مرتبط در فرم‌های بزرگ.</p><h3>نمونه کاربردی</h3><p>کد را در فایل HTML آزمایش کن و رفتار آن را در مرورگر بررسی کن.</p><pre><code>&lt;fieldset&gt;&lt;legend&gt;اطلاعات حساب&lt;/legend&gt;&lt;label for=\"u\"&gt;شناسه&lt;/label&gt;&lt;input id=\"u\" name=\"user\"&gt;&lt;/fieldset&gt;</code></pre><h3>تمرین</h3><p>فرم تنظیمات را به گروه حساب و اعلان تقسیم کن.</p><h3>نکته فنی</h3><p>این قابلیت به‌تنهایی backend یا امنیت کامل ایجاد نمی‌کند؛ رفتار را در مرورگر هدف آزمایش کن و محدودیت آن را در نظر بگیر.</p><h3>معیار موفقیت</h3><ul><li>عنصر و ویژگی با هدف درست انتخاب شده باشد.</li><li>رفتار صفحه با صفحه‌کلید بررسی شده باشد.</li><li>نیاز احتمالی به CSS، JavaScript یا backend را تشخیص بدهی.</li></ul>","starter_code":"<fieldset><legend>اطلاعات حساب</legend><label for=\"u\">شناسه</label><input id=\"u\" name=\"user\"></fieldset>","exercise":"فرم تنظیمات را به گروه حساب و اعلان تقسیم کن.","status":"published","sort_order":1,"estimated_minutes":25},{"id":"curriculum-324-html-intermediate-02","course_id":"html-intermediate","title":"اعتبارسنجی pattern","slug":"html-intermediate-02","summary":"اعتبارسنجی pattern: محدودکردن قالب ورودی با عبارت منظم؛ اعتبارسنجی سرور همچنان ضروری است.","content_html":"<h3>هدف درس</h3><p>محدودکردن قالب ورودی با عبارت منظم؛ اعتبارسنجی سرور همچنان ضروری است.</p><h3>نمونه کاربردی</h3><p>کد را در فایل HTML آزمایش کن و رفتار آن را در مرورگر بررسی کن.</p><pre><code>&lt;input name=\"code\" pattern=\"[a-z0-9]{12}\" title=\"۱۲ حرف کوچک یا رقم\" required&gt;</code></pre><h3>تمرین</h3><p>شناسه ۱۲ نویسه‌ای بساز و حالت‌های نامعتبر را آزمایش کن.</p><h3>نکته فنی</h3><p>این قابلیت به‌تنهایی backend یا امنیت کامل ایجاد نمی‌کند؛ رفتار را در مرورگر هدف آزمایش کن و محدودیت آن را در نظر بگیر.</p><h3>معیار موفقیت</h3><ul><li>عنصر و ویژگی با هدف درست انتخاب شده باشد.</li><li>رفتار صفحه با صفحه‌کلید بررسی شده باشد.</li><li>نیاز احتمالی به CSS، JavaScript یا backend را تشخیص بدهی.</li></ul>","starter_code":"<input name=\"code\" pattern=\"[a-z0-9]{12}\" title=\"۱۲ حرف کوچک یا رقم\" required>","exercise":"شناسه ۱۲ نویسه‌ای بساز و حالت‌های نامعتبر را آزمایش کن.","status":"published","sort_order":2,"estimated_minutes":30},{"id":"curriculum-324-html-intermediate-03","course_id":"html-intermediate","title":"aria-describedby","slug":"html-intermediate-03","summary":"aria-describedby: اتصال توضیح کمکی یا پیام خطا به ورودی فرم.","content_html":"<h3>هدف درس</h3><p>اتصال توضیح کمکی یا پیام خطا به ورودی فرم.</p><h3>نمونه کاربردی</h3><p>کد را در فایل HTML آزمایش کن و رفتار آن را در مرورگر بررسی کن.</p><pre><code>&lt;label for=\"pw\"&gt;رمز&lt;/label&gt;&lt;input id=\"pw\" type=\"password\" aria-describedby=\"hint\"&gt;&lt;p id=\"hint\"&gt;حداقل ۱۰ نویسه&lt;/p&gt;</code></pre><h3>تمرین</h3><p>برای دو ورودی توضیح کمکی متصل کن.</p><h3>نکته فنی</h3><p>این قابلیت به‌تنهایی backend یا امنیت کامل ایجاد نمی‌کند؛ رفتار را در مرورگر هدف آزمایش کن و محدودیت آن را در نظر بگیر.</p><h3>معیار موفقیت</h3><ul><li>عنصر و ویژگی با هدف درست انتخاب شده باشد.</li><li>رفتار صفحه با صفحه‌کلید بررسی شده باشد.</li><li>نیاز احتمالی به CSS، JavaScript یا backend را تشخیص بدهی.</li></ul>","starter_code":"<label for=\"pw\">رمز</label><input id=\"pw\" type=\"password\" aria-describedby=\"hint\"><p id=\"hint\">حداقل ۱۰ نویسه</p>","exercise":"برای دو ورودی توضیح کمکی متصل کن.","status":"published","sort_order":3,"estimated_minutes":35},{"id":"curriculum-324-html-intermediate-04","course_id":"html-intermediate","title":"autocomplete","slug":"html-intermediate-04","summary":"autocomplete: اعلام نوع داده مورد انتظار برای تکمیل خودکار مرورگر.","content_html":"<h3>هدف درس</h3><p>اعلام نوع داده مورد انتظار برای تکمیل خودکار مرورگر.</p><h3>نمونه کاربردی</h3><p>کد را در فایل HTML آزمایش کن و رفتار آن را در مرورگر بررسی کن.</p><pre><code>&lt;input autocomplete=\"name\"&gt;&lt;input type=\"email\" autocomplete=\"email\"&gt;&lt;input type=\"password\" autocomplete=\"new-password\"&gt;</code></pre><h3>تمرین</h3><p>برای نام، ایمیل، شناسه و رمز token مناسب انتخاب کن.</p><h3>نکته فنی</h3><p>این قابلیت به‌تنهایی backend یا امنیت کامل ایجاد نمی‌کند؛ رفتار را در مرورگر هدف آزمایش کن و محدودیت آن را در نظر بگیر.</p><h3>معیار موفقیت</h3><ul><li>عنصر و ویژگی با هدف درست انتخاب شده باشد.</li><li>رفتار صفحه با صفحه‌کلید بررسی شده باشد.</li><li>نیاز احتمالی به CSS، JavaScript یا backend را تشخیص بدهی.</li></ul>","starter_code":"<input autocomplete=\"name\"><input type=\"email\" autocomplete=\"email\"><input type=\"password\" autocomplete=\"new-password\">","exercise":"برای نام، ایمیل، شناسه و رمز token مناسب انتخاب کن.","status":"published","sort_order":4,"estimated_minutes":40},{"id":"curriculum-324-html-intermediate-05","course_id":"html-intermediate","title":"datalist","slug":"html-intermediate-05","summary":"datalist: ارائه پیشنهاد برای input بدون محدودکردن قطعی مقدار.","content_html":"<h3>هدف درس</h3><p>ارائه پیشنهاد برای input بدون محدودکردن قطعی مقدار.</p><h3>نمونه کاربردی</h3><p>کد را در فایل HTML آزمایش کن و رفتار آن را در مرورگر بررسی کن.</p><pre><code>&lt;input list=\"topics\"&gt;&lt;datalist id=\"topics\"&gt;&lt;option value=\"طراحی وب\"&gt;&lt;option value=\"برنامه‌نویسی\"&gt;&lt;/datalist&gt;</code></pre><h3>تمرین</h3><p>پیشنهاد موضوع بساز و مقدار دلخواه خارج از فهرست را امتحان کن.</p><h3>نکته فنی</h3><p>این قابلیت به‌تنهایی backend یا امنیت کامل ایجاد نمی‌کند؛ رفتار را در مرورگر هدف آزمایش کن و محدودیت آن را در نظر بگیر.</p><h3>معیار موفقیت</h3><ul><li>عنصر و ویژگی با هدف درست انتخاب شده باشد.</li><li>رفتار صفحه با صفحه‌کلید بررسی شده باشد.</li><li>نیاز احتمالی به CSS، JavaScript یا backend را تشخیص بدهی.</li></ul>","starter_code":"<input list=\"topics\"><datalist id=\"topics\"><option value=\"طراحی وب\"><option value=\"برنامه‌نویسی\"></datalist>","exercise":"پیشنهاد موضوع بساز و مقدار دلخواه خارج از فهرست را امتحان کن.","status":"published","sort_order":5,"estimated_minutes":25},{"id":"curriculum-324-html-intermediate-06","course_id":"html-intermediate","title":"input فایل و accept","slug":"html-intermediate-06","summary":"input فایل و accept: پیشنهاد نوع فایل در انتخاب‌گر؛ بررسی واقعی فایل وظیفه سرور است.","content_html":"<h3>هدف درس</h3><p>پیشنهاد نوع فایل در انتخاب‌گر؛ بررسی واقعی فایل وظیفه سرور است.</p><h3>نمونه کاربردی</h3><p>کد را در فایل HTML آزمایش کن و رفتار آن را در مرورگر بررسی کن.</p><pre><code>&lt;input type=\"file\" accept=\"image/png,image/jpeg,image/webp\"&gt;</code></pre><h3>تمرین</h3><p>ورودی تصویر بساز و محدودیت accept را شرح بده.</p><h3>نکته فنی</h3><p>این قابلیت به‌تنهایی backend یا امنیت کامل ایجاد نمی‌کند؛ رفتار را در مرورگر هدف آزمایش کن و محدودیت آن را در نظر بگیر.</p><h3>معیار موفقیت</h3><ul><li>عنصر و ویژگی با هدف درست انتخاب شده باشد.</li><li>رفتار صفحه با صفحه‌کلید بررسی شده باشد.</li><li>نیاز احتمالی به CSS، JavaScript یا backend را تشخیص بدهی.</li></ul>","starter_code":"<input type=\"file\" accept=\"image/png,image/jpeg,image/webp\">","exercise":"ورودی تصویر بساز و محدودیت accept را شرح بده.","status":"published","sort_order":6,"estimated_minutes":30},{"id":"curriculum-324-html-intermediate-07","course_id":"html-intermediate","title":"انتخاب چند فایل","slug":"html-intermediate-07","summary":"انتخاب چند فایل: multiple امکان انتخاب چند فایل را فراهم می‌کند.","content_html":"<h3>هدف درس</h3><p>multiple امکان انتخاب چند فایل را فراهم می‌کند.</p><h3>نمونه کاربردی</h3><p>کد را در فایل HTML آزمایش کن و رفتار آن را در مرورگر بررسی کن.</p><pre><code>&lt;input type=\"file\" name=\"files\" multiple accept=\".pdf,image/*\"&gt;</code></pre><h3>تمرین</h3><p>ورودی چندفایلی و راهنمای استفاده بساز.</p><h3>نکته فنی</h3><p>این قابلیت به‌تنهایی backend یا امنیت کامل ایجاد نمی‌کند؛ رفتار را در مرورگر هدف آزمایش کن و محدودیت آن را در نظر بگیر.</p><h3>معیار موفقیت</h3><ul><li>عنصر و ویژگی با هدف درست انتخاب شده باشد.</li><li>رفتار صفحه با صفحه‌کلید بررسی شده باشد.</li><li>نیاز احتمالی به CSS، JavaScript یا backend را تشخیص بدهی.</li></ul>","starter_code":"<input type=\"file\" name=\"files\" multiple accept=\".pdf,image/*\">","exercise":"ورودی چندفایلی و راهنمای استفاده بساز.","status":"published","sort_order":7,"estimated_minutes":35},{"id":"curriculum-324-html-intermediate-08","course_id":"html-intermediate","title":"readonly در برابر disabled","slug":"html-intermediate-08","summary":"readonly در برابر disabled: readonly مقدار را قفل می‌کند؛ disabled کنترل را غیرفعال و معمولاً از ارسال فرم خارج می‌کند.","content_html":"<h3>هدف درس</h3><p>readonly مقدار را قفل می‌کند؛ disabled کنترل را غیرفعال و معمولاً از ارسال فرم خارج می‌کند.</p><h3>نمونه کاربردی</h3><p>کد را در فایل HTML آزمایش کن و رفتار آن را در مرورگر بررسی کن.</p><pre><code>&lt;input name=\"id\" value=\"ab12\" readonly&gt;&lt;input name=\"locked\" value=\"قفل\" disabled&gt;</code></pre><h3>تمرین</h3><p>رفتار ارسال مقدار این دو را مقایسه کن.</p><h3>نکته فنی</h3><p>این قابلیت به‌تنهایی backend یا امنیت کامل ایجاد نمی‌کند؛ رفتار را در مرورگر هدف آزمایش کن و محدودیت آن را در نظر بگیر.</p><h3>معیار موفقیت</h3><ul><li>عنصر و ویژگی با هدف درست انتخاب شده باشد.</li><li>رفتار صفحه با صفحه‌کلید بررسی شده باشد.</li><li>نیاز احتمالی به CSS، JavaScript یا backend را تشخیص بدهی.</li></ul>","starter_code":"<input name=\"id\" value=\"ab12\" readonly><input name=\"locked\" value=\"قفل\" disabled>","exercise":"رفتار ارسال مقدار این دو را مقایسه کن.","status":"published","sort_order":8,"estimated_minutes":40},{"id":"curriculum-324-html-intermediate-09","course_id":"html-intermediate","title":"formaction و formmethod","slug":"html-intermediate-09","summary":"formaction و formmethod: تغییر مقصد یا روش ارسال برای یک دکمه submit خاص.","content_html":"<h3>هدف درس</h3><p>تغییر مقصد یا روش ارسال برای یک دکمه submit خاص.</p><h3>نمونه کاربردی</h3><p>کد را در فایل HTML آزمایش کن و رفتار آن را در مرورگر بررسی کن.</p><pre><code>&lt;form action=\"/save\" method=\"post\"&gt;&lt;button&gt;ذخیره&lt;/button&gt;&lt;button formaction=\"/preview\" formmethod=\"get\"&gt;پیش‌نمایش&lt;/button&gt;&lt;/form&gt;</code></pre><h3>تمرین</h3><p>فرمی با دکمه‌های ذخیره و پیش‌نمایش بساز.</p><h3>نکته فنی</h3><p>این قابلیت به‌تنهایی backend یا امنیت کامل ایجاد نمی‌کند؛ رفتار را در مرورگر هدف آزمایش کن و محدودیت آن را در نظر بگیر.</p><h3>معیار موفقیت</h3><ul><li>عنصر و ویژگی با هدف درست انتخاب شده باشد.</li><li>رفتار صفحه با صفحه‌کلید بررسی شده باشد.</li><li>نیاز احتمالی به CSS، JavaScript یا backend را تشخیص بدهی.</li></ul>","starter_code":"<form action=\"/save\" method=\"post\"><button>ذخیره</button><button formaction=\"/preview\" formmethod=\"get\">پیش‌نمایش</button></form>","exercise":"فرمی با دکمه‌های ذخیره و پیش‌نمایش بساز.","status":"published","sort_order":9,"estimated_minutes":25},{"id":"curriculum-324-html-intermediate-10","course_id":"html-intermediate","title":"multipart/form-data","slug":"html-intermediate-10","summary":"multipart/form-data: کدگذاری لازم فرم برای ارسال فایل با درخواست POST.","content_html":"<h3>هدف درس</h3><p>کدگذاری لازم فرم برای ارسال فایل با درخواست POST.</p><h3>نمونه کاربردی</h3><p>کد را در فایل HTML آزمایش کن و رفتار آن را در مرورگر بررسی کن.</p><pre><code>&lt;form action=\"/upload\" method=\"post\" enctype=\"multipart/form-data\"&gt;&lt;input type=\"file\" name=\"file\"&gt;&lt;button&gt;بارگذاری&lt;/button&gt;&lt;/form&gt;</code></pre><h3>تمرین</h3><p>فرم بارگذاری بساز و نقش enctype را توضیح بده.</p><h3>نکته فنی</h3><p>این قابلیت به‌تنهایی backend یا امنیت کامل ایجاد نمی‌کند؛ رفتار را در مرورگر هدف آزمایش کن و محدودیت آن را در نظر بگیر.</p><h3>معیار موفقیت</h3><ul><li>عنصر و ویژگی با هدف درست انتخاب شده باشد.</li><li>رفتار صفحه با صفحه‌کلید بررسی شده باشد.</li><li>نیاز احتمالی به CSS، JavaScript یا backend را تشخیص بدهی.</li></ul>","starter_code":"<form action=\"/upload\" method=\"post\" enctype=\"multipart/form-data\"><input type=\"file\" name=\"file\"><button>بارگذاری</button></form>","exercise":"فرم بارگذاری بساز و نقش enctype را توضیح بده.","status":"published","sort_order":10,"estimated_minutes":30},{"id":"curriculum-324-html-intermediate-11","course_id":"html-intermediate","title":"optgroup","slug":"html-intermediate-11","summary":"optgroup: گروه‌بندی گزینه‌های مرتبط داخل select.","content_html":"<h3>هدف درس</h3><p>گروه‌بندی گزینه‌های مرتبط داخل select.</p><h3>نمونه کاربردی</h3><p>کد را در فایل HTML آزمایش کن و رفتار آن را در مرورگر بررسی کن.</p><pre><code>&lt;select&gt;&lt;optgroup label=\"وب\"&gt;&lt;option&gt;HTML&lt;/option&gt;&lt;option&gt;CSS&lt;/option&gt;&lt;/optgroup&gt;&lt;optgroup label=\"کدنویسی\"&gt;&lt;option&gt;JavaScript&lt;/option&gt;&lt;/optgroup&gt;&lt;/select&gt;</code></pre><h3>تمرین</h3><p>گزینه‌های دوره را در گروه‌های موضوعی بچین.</p><h3>نکته فنی</h3><p>این قابلیت به‌تنهایی backend یا امنیت کامل ایجاد نمی‌کند؛ رفتار را در مرورگر هدف آزمایش کن و محدودیت آن را در نظر بگیر.</p><h3>معیار موفقیت</h3><ul><li>عنصر و ویژگی با هدف درست انتخاب شده باشد.</li><li>رفتار صفحه با صفحه‌کلید بررسی شده باشد.</li><li>نیاز احتمالی به CSS، JavaScript یا backend را تشخیص بدهی.</li></ul>","starter_code":"<select><optgroup label=\"وب\"><option>HTML</option><option>CSS</option></optgroup><optgroup label=\"کدنویسی\"><option>JavaScript</option></optgroup></select>","exercise":"گزینه‌های دوره را در گروه‌های موضوعی بچین.","status":"published","sort_order":11,"estimated_minutes":35},{"id":"curriculum-324-html-intermediate-12","course_id":"html-intermediate","title":"output","slug":"html-intermediate-12","summary":"output: عنصر معنایی برای نمایش نتیجه محاسبه یا عملیات.","content_html":"<h3>هدف درس</h3><p>عنصر معنایی برای نمایش نتیجه محاسبه یا عملیات.</p><h3>نمونه کاربردی</h3><p>کد را در فایل HTML آزمایش کن و رفتار آن را در مرورگر بررسی کن.</p><pre><code>&lt;form oninput=\"sum.value=Number(a.value)+Number(b.value)\"&gt;&lt;input id=\"a\" type=\"number\" value=\"2\"&gt;&lt;input id=\"b\" type=\"number\" value=\"3\"&gt;&lt;output name=\"sum\" for=\"a b\"&gt;5&lt;/output&gt;&lt;/form&gt;</code></pre><h3>تمرین</h3><p>جمع دو ورودی را نمایش بده و نقش JavaScript را مشخص کن.</p><h3>نکته فنی</h3><p>این قابلیت به‌تنهایی backend یا امنیت کامل ایجاد نمی‌کند؛ رفتار را در مرورگر هدف آزمایش کن و محدودیت آن را در نظر بگیر.</p><h3>معیار موفقیت</h3><ul><li>عنصر و ویژگی با هدف درست انتخاب شده باشد.</li><li>رفتار صفحه با صفحه‌کلید بررسی شده باشد.</li><li>نیاز احتمالی به CSS، JavaScript یا backend را تشخیص بدهی.</li></ul>","starter_code":"<form oninput=\"sum.value=Number(a.value)+Number(b.value)\"><input id=\"a\" type=\"number\" value=\"2\"><input id=\"b\" type=\"number\" value=\"3\"><output name=\"sum\" for=\"a b\">5</output></form>","exercise":"جمع دو ورودی را نمایش بده و نقش JavaScript را مشخص کن.","status":"published","sort_order":12,"estimated_minutes":40},{"id":"curriculum-324-html-intermediate-13","course_id":"html-intermediate","title":"progress","slug":"html-intermediate-13","summary":"progress: نمایش میزان پیشرفت یک کار در محدوده مشخص.","content_html":"<h3>هدف درس</h3><p>نمایش میزان پیشرفت یک کار در محدوده مشخص.</p><h3>نمونه کاربردی</h3><p>کد را در فایل HTML آزمایش کن و رفتار آن را در مرورگر بررسی کن.</p><pre><code>&lt;progress value=\"35\" max=\"100\"&gt;35%&lt;/progress&gt;</code></pre><h3>تمرین</h3><p>نمونه progress مشخص و نامشخص بساز.</p><h3>نکته فنی</h3><p>این قابلیت به‌تنهایی backend یا امنیت کامل ایجاد نمی‌کند؛ رفتار را در مرورگر هدف آزمایش کن و محدودیت آن را در نظر بگیر.</p><h3>معیار موفقیت</h3><ul><li>عنصر و ویژگی با هدف درست انتخاب شده باشد.</li><li>رفتار صفحه با صفحه‌کلید بررسی شده باشد.</li><li>نیاز احتمالی به CSS، JavaScript یا backend را تشخیص بدهی.</li></ul>","starter_code":"<progress value=\"35\" max=\"100\">35%</progress>","exercise":"نمونه progress مشخص و نامشخص بساز.","status":"published","sort_order":13,"estimated_minutes":25},{"id":"curriculum-324-html-intermediate-14","course_id":"html-intermediate","title":"meter","slug":"html-intermediate-14","summary":"meter: نمایش سنجه مقداری مانند ظرفیت یا امتیاز در یک بازه.","content_html":"<h3>هدف درس</h3><p>نمایش سنجه مقداری مانند ظرفیت یا امتیاز در یک بازه.</p><h3>نمونه کاربردی</h3><p>کد را در فایل HTML آزمایش کن و رفتار آن را در مرورگر بررسی کن.</p><pre><code>&lt;meter min=\"0\" max=\"100\" low=\"40\" high=\"80\" optimum=\"95\" value=\"72\"&gt;72&lt;/meter&gt;</code></pre><h3>تمرین</h3><p>meter ظرفیت ذخیره‌سازی طراحی کن.</p><h3>نکته فنی</h3><p>این قابلیت به‌تنهایی backend یا امنیت کامل ایجاد نمی‌کند؛ رفتار را در مرورگر هدف آزمایش کن و محدودیت آن را در نظر بگیر.</p><h3>معیار موفقیت</h3><ul><li>عنصر و ویژگی با هدف درست انتخاب شده باشد.</li><li>رفتار صفحه با صفحه‌کلید بررسی شده باشد.</li><li>نیاز احتمالی به CSS، JavaScript یا backend را تشخیص بدهی.</li></ul>","starter_code":"<meter min=\"0\" max=\"100\" low=\"40\" high=\"80\" optimum=\"95\" value=\"72\">72</meter>","exercise":"meter ظرفیت ذخیره‌سازی طراحی کن.","status":"published","sort_order":14,"estimated_minutes":30},{"id":"curriculum-324-html-intermediate-15","course_id":"html-intermediate","title":"details و summary","slug":"html-intermediate-15","summary":"details و summary: ساخت بخش افشونده بومی با عنوان قابل فعال‌سازی.","content_html":"<h3>هدف درس</h3><p>ساخت بخش افشونده بومی با عنوان قابل فعال‌سازی.</p><h3>نمونه کاربردی</h3><p>کد را در فایل HTML آزمایش کن و رفتار آن را در مرورگر بررسی کن.</p><pre><code>&lt;details&gt;&lt;summary&gt;پیش‌نیازها&lt;/summary&gt;&lt;p&gt;آشنایی با مرورگر کافی است.&lt;/p&gt;&lt;/details&gt;</code></pre><h3>تمرین</h3><p>سه پرسش متداول با عنوان‌های روشن بساز.</p><h3>نکته فنی</h3><p>این قابلیت به‌تنهایی backend یا امنیت کامل ایجاد نمی‌کند؛ رفتار را در مرورگر هدف آزمایش کن و محدودیت آن را در نظر بگیر.</p><h3>معیار موفقیت</h3><ul><li>عنصر و ویژگی با هدف درست انتخاب شده باشد.</li><li>رفتار صفحه با صفحه‌کلید بررسی شده باشد.</li><li>نیاز احتمالی به CSS، JavaScript یا backend را تشخیص بدهی.</li></ul>","starter_code":"<details><summary>پیش‌نیازها</summary><p>آشنایی با مرورگر کافی است.</p></details>","exercise":"سه پرسش متداول با عنوان‌های روشن بساز.","status":"published","sort_order":15,"estimated_minutes":35},{"id":"curriculum-324-html-intermediate-16","course_id":"html-intermediate","title":"dialog","slug":"html-intermediate-16","summary":"dialog: پنجره محاوره‌ای بومی با قابلیت بازشدن modal.","content_html":"<h3>هدف درس</h3><p>پنجره محاوره‌ای بومی با قابلیت بازشدن modal.</p><h3>نمونه کاربردی</h3><p>کد را در فایل HTML آزمایش کن و رفتار آن را در مرورگر بررسی کن.</p><pre><code>&lt;dialog id=\"d\"&gt;&lt;h2&gt;راهنما&lt;/h2&gt;&lt;form method=\"dialog\"&gt;&lt;button&gt;بستن&lt;/button&gt;&lt;/form&gt;&lt;/dialog&gt;&lt;button onclick=\"d.showModal()\"&gt;نمایش&lt;/button&gt;</code></pre><h3>تمرین</h3><p>پنجره راهنما بساز و مسیر بستن و فوکوس را آزمایش کن.</p><h3>نکته فنی</h3><p>این قابلیت به‌تنهایی backend یا امنیت کامل ایجاد نمی‌کند؛ رفتار را در مرورگر هدف آزمایش کن و محدودیت آن را در نظر بگیر.</p><h3>معیار موفقیت</h3><ul><li>عنصر و ویژگی با هدف درست انتخاب شده باشد.</li><li>رفتار صفحه با صفحه‌کلید بررسی شده باشد.</li><li>نیاز احتمالی به CSS، JavaScript یا backend را تشخیص بدهی.</li></ul>","starter_code":"<dialog id=\"d\"><h2>راهنما</h2><form method=\"dialog\"><button>بستن</button></form></dialog><button onclick=\"d.showModal()\">نمایش</button>","exercise":"پنجره راهنما بساز و مسیر بستن و فوکوس را آزمایش کن.","status":"published","sort_order":16,"estimated_minutes":40},{"id":"curriculum-324-html-intermediate-17","course_id":"html-intermediate","title":"picture","slug":"html-intermediate-17","summary":"picture: انتخاب منبع تصویر بر اساس اندازه صفحه یا نوع فایل.","content_html":"<h3>هدف درس</h3><p>انتخاب منبع تصویر بر اساس اندازه صفحه یا نوع فایل.</p><h3>نمونه کاربردی</h3><p>کد را در فایل HTML آزمایش کن و رفتار آن را در مرورگر بررسی کن.</p><pre><code>&lt;picture&gt;&lt;source media=\"(max-width:600px)\" srcset=\"small.webp\"&gt;&lt;source type=\"image/avif\" srcset=\"banner.avif\"&gt;&lt;img src=\"banner.jpg\" alt=\"نمای پروژه\"&gt;&lt;/picture&gt;</code></pre><h3>تمرین</h3><p>نسخه موبایل و دسکتاپ تصویر معرفی کن.</p><h3>نکته فنی</h3><p>این قابلیت به‌تنهایی backend یا امنیت کامل ایجاد نمی‌کند؛ رفتار را در مرورگر هدف آزمایش کن و محدودیت آن را در نظر بگیر.</p><h3>معیار موفقیت</h3><ul><li>عنصر و ویژگی با هدف درست انتخاب شده باشد.</li><li>رفتار صفحه با صفحه‌کلید بررسی شده باشد.</li><li>نیاز احتمالی به CSS، JavaScript یا backend را تشخیص بدهی.</li></ul>","starter_code":"<picture><source media=\"(max-width:600px)\" srcset=\"small.webp\"><source type=\"image/avif\" srcset=\"banner.avif\"><img src=\"banner.jpg\" alt=\"نمای پروژه\"></picture>","exercise":"نسخه موبایل و دسکتاپ تصویر معرفی کن.","status":"published","sort_order":17,"estimated_minutes":25},{"id":"curriculum-324-html-intermediate-18","course_id":"html-intermediate","title":"srcset و sizes","slug":"html-intermediate-18","summary":"srcset و sizes: معرفی چند وضوح تصویر برای انتخاب هوشمند مرورگر.","content_html":"<h3>هدف درس</h3><p>معرفی چند وضوح تصویر برای انتخاب هوشمند مرورگر.</p><h3>نمونه کاربردی</h3><p>کد را در فایل HTML آزمایش کن و رفتار آن را در مرورگر بررسی کن.</p><pre><code>&lt;img src=\"a800.jpg\" srcset=\"a400.jpg 400w, a800.jpg 800w, a1200.jpg 1200w\" sizes=\"(max-width:600px) 100vw,800px\" alt=\"دوره\"&gt;</code></pre><h3>تمرین</h3><p>سه فایل واقعی و عرض صحیح آن‌ها را تنظیم کن.</p><h3>نکته فنی</h3><p>این قابلیت به‌تنهایی backend یا امنیت کامل ایجاد نمی‌کند؛ رفتار را در مرورگر هدف آزمایش کن و محدودیت آن را در نظر بگیر.</p><h3>معیار موفقیت</h3><ul><li>عنصر و ویژگی با هدف درست انتخاب شده باشد.</li><li>رفتار صفحه با صفحه‌کلید بررسی شده باشد.</li><li>نیاز احتمالی به CSS، JavaScript یا backend را تشخیص بدهی.</li></ul>","starter_code":"<img src=\"a800.jpg\" srcset=\"a400.jpg 400w, a800.jpg 800w, a1200.jpg 1200w\" sizes=\"(max-width:600px) 100vw,800px\" alt=\"دوره\">","exercise":"سه فایل واقعی و عرض صحیح آن‌ها را تنظیم کن.","status":"published","sort_order":18,"estimated_minutes":30},{"id":"curriculum-324-html-intermediate-19","course_id":"html-intermediate","title":"figure و figcaption","slug":"html-intermediate-19","summary":"figure و figcaption: گروه‌بندی تصویر یا نمودار مستقل با شرح مرتبط.","content_html":"<h3>هدف درس</h3><p>گروه‌بندی تصویر یا نمودار مستقل با شرح مرتبط.</p><h3>نمونه کاربردی</h3><p>کد را در فایل HTML آزمایش کن و رفتار آن را در مرورگر بررسی کن.</p><pre><code>&lt;figure&gt;&lt;img src=\"tree.png\" alt=\"درخت عناصر HTML\"&gt;&lt;figcaption&gt;شکل ۱: ساختار سند&lt;/figcaption&gt;&lt;/figure&gt;</code></pre><h3>تمرین</h3><p>برای نمودار آموزشی شرح دقیق بنویس.</p><h3>نکته فنی</h3><p>این قابلیت به‌تنهایی backend یا امنیت کامل ایجاد نمی‌کند؛ رفتار را در مرورگر هدف آزمایش کن و محدودیت آن را در نظر بگیر.</p><h3>معیار موفقیت</h3><ul><li>عنصر و ویژگی با هدف درست انتخاب شده باشد.</li><li>رفتار صفحه با صفحه‌کلید بررسی شده باشد.</li><li>نیاز احتمالی به CSS، JavaScript یا backend را تشخیص بدهی.</li></ul>","starter_code":"<figure><img src=\"tree.png\" alt=\"درخت عناصر HTML\"><figcaption>شکل ۱: ساختار سند</figcaption></figure>","exercise":"برای نمودار آموزشی شرح دقیق بنویس.","status":"published","sort_order":19,"estimated_minutes":35},{"id":"curriculum-324-html-intermediate-20","course_id":"html-intermediate","title":"SVG دسترس‌پذیر","slug":"html-intermediate-20","summary":"SVG دسترس‌پذیر: گرافیک برداری درون‌خطی با عنوان قابل شناسایی.","content_html":"<h3>هدف درس</h3><p>گرافیک برداری درون‌خطی با عنوان قابل شناسایی.</p><h3>نمونه کاربردی</h3><p>کد را در فایل HTML آزمایش کن و رفتار آن را در مرورگر بررسی کن.</p><pre><code>&lt;svg viewBox=\"0 0 100 60\" role=\"img\" aria-labelledby=\"t\"&gt;&lt;title id=\"t\"&gt;دو ستون&lt;/title&gt;&lt;rect x=\"10\" y=\"25\" width=\"20\" height=\"30\"/&gt;&lt;rect x=\"50\" y=\"10\" width=\"20\" height=\"45\"/&gt;&lt;/svg&gt;</code></pre><h3>تمرین</h3><p>SVG با دو شکل و عنوان توصیفی بساز.</p><h3>نکته فنی</h3><p>این قابلیت به‌تنهایی backend یا امنیت کامل ایجاد نمی‌کند؛ رفتار را در مرورگر هدف آزمایش کن و محدودیت آن را در نظر بگیر.</p><h3>معیار موفقیت</h3><ul><li>عنصر و ویژگی با هدف درست انتخاب شده باشد.</li><li>رفتار صفحه با صفحه‌کلید بررسی شده باشد.</li><li>نیاز احتمالی به CSS، JavaScript یا backend را تشخیص بدهی.</li></ul>","starter_code":"<svg viewBox=\"0 0 100 60\" role=\"img\" aria-labelledby=\"t\"><title id=\"t\">دو ستون</title><rect x=\"10\" y=\"25\" width=\"20\" height=\"30\"/><rect x=\"50\" y=\"10\" width=\"20\" height=\"45\"/></svg>","exercise":"SVG با دو شکل و عنوان توصیفی بساز.","status":"published","sort_order":20,"estimated_minutes":40},{"id":"curriculum-324-html-intermediate-21","course_id":"html-intermediate","title":"noscript","slug":"html-intermediate-21","summary":"noscript: نمایش پیام جایگزین در صورت غیرفعال بودن JavaScript.","content_html":"<h3>هدف درس</h3><p>نمایش پیام جایگزین در صورت غیرفعال بودن JavaScript.</p><h3>نمونه کاربردی</h3><p>کد را در فایل HTML آزمایش کن و رفتار آن را در مرورگر بررسی کن.</p><pre><code>&lt;noscript&gt;&lt;p&gt;برای این قابلیت JavaScript را فعال کن.&lt;/p&gt;&lt;/noscript&gt;</code></pre><h3>تمرین</h3><p>پیام جایگزین یک قابلیت وابسته به اسکریپت بنویس.</p><h3>نکته فنی</h3><p>این قابلیت به‌تنهایی backend یا امنیت کامل ایجاد نمی‌کند؛ رفتار را در مرورگر هدف آزمایش کن و محدودیت آن را در نظر بگیر.</p><h3>معیار موفقیت</h3><ul><li>عنصر و ویژگی با هدف درست انتخاب شده باشد.</li><li>رفتار صفحه با صفحه‌کلید بررسی شده باشد.</li><li>نیاز احتمالی به CSS، JavaScript یا backend را تشخیص بدهی.</li></ul>","starter_code":"<noscript><p>برای این قابلیت JavaScript را فعال کن.</p></noscript>","exercise":"پیام جایگزین یک قابلیت وابسته به اسکریپت بنویس.","status":"published","sort_order":21,"estimated_minutes":25},{"id":"curriculum-324-html-intermediate-22","course_id":"html-intermediate","title":"loading lazy","slug":"html-intermediate-22","summary":"loading lazy: به‌تعویق‌انداختن دریافت تصویر خارج از محدوده دید.","content_html":"<h3>هدف درس</h3><p>به‌تعویق‌انداختن دریافت تصویر خارج از محدوده دید.</p><h3>نمونه کاربردی</h3><p>کد را در فایل HTML آزمایش کن و رفتار آن را در مرورگر بررسی کن.</p><pre><code>&lt;img src=\"gallery.jpg\" alt=\"پروژه\" width=\"800\" height=\"500\" loading=\"lazy\"&gt;</code></pre><h3>تمرین</h3><p>برای تصاویر پایین صفحه lazy و ابعاد ثابت بگذار.</p><h3>نکته فنی</h3><p>این قابلیت به‌تنهایی backend یا امنیت کامل ایجاد نمی‌کند؛ رفتار را در مرورگر هدف آزمایش کن و محدودیت آن را در نظر بگیر.</p><h3>معیار موفقیت</h3><ul><li>عنصر و ویژگی با هدف درست انتخاب شده باشد.</li><li>رفتار صفحه با صفحه‌کلید بررسی شده باشد.</li><li>نیاز احتمالی به CSS، JavaScript یا backend را تشخیص بدهی.</li></ul>","starter_code":"<img src=\"gallery.jpg\" alt=\"پروژه\" width=\"800\" height=\"500\" loading=\"lazy\">","exercise":"برای تصاویر پایین صفحه lazy و ابعاد ثابت بگذار.","status":"published","sort_order":22,"estimated_minutes":30},{"id":"curriculum-324-html-intermediate-23","course_id":"html-intermediate","title":"fetchpriority","slug":"html-intermediate-23","summary":"fetchpriority: پیشنهاد اولویت دریافت منبع مهم برای مرورگر.","content_html":"<h3>هدف درس</h3><p>پیشنهاد اولویت دریافت منبع مهم برای مرورگر.</p><h3>نمونه کاربردی</h3><p>کد را در فایل HTML آزمایش کن و رفتار آن را در مرورگر بررسی کن.</p><pre><code>&lt;img src=\"hero.webp\" alt=\"تصویر اصلی\" width=\"1200\" height=\"600\" fetchpriority=\"high\"&gt;</code></pre><h3>تمرین</h3><p>برای تصویر اصلی و فرعی اولویت مناسب تعیین کن.</p><h3>نکته فنی</h3><p>این قابلیت به‌تنهایی backend یا امنیت کامل ایجاد نمی‌کند؛ رفتار را در مرورگر هدف آزمایش کن و محدودیت آن را در نظر بگیر.</p><h3>معیار موفقیت</h3><ul><li>عنصر و ویژگی با هدف درست انتخاب شده باشد.</li><li>رفتار صفحه با صفحه‌کلید بررسی شده باشد.</li><li>نیاز احتمالی به CSS، JavaScript یا backend را تشخیص بدهی.</li></ul>","starter_code":"<img src=\"hero.webp\" alt=\"تصویر اصلی\" width=\"1200\" height=\"600\" fetchpriority=\"high\">","exercise":"برای تصویر اصلی و فرعی اولویت مناسب تعیین کن.","status":"published","sort_order":23,"estimated_minutes":35},{"id":"curriculum-324-html-intermediate-24","course_id":"html-intermediate","title":"iframe sandbox","slug":"html-intermediate-24","summary":"iframe sandbox: محدودکردن قابلیت‌های محتوای جاسازی‌شده.","content_html":"<h3>هدف درس</h3><p>محدودکردن قابلیت‌های محتوای جاسازی‌شده.</p><h3>نمونه کاربردی</h3><p>کد را در فایل HTML آزمایش کن و رفتار آن را در مرورگر بررسی کن.</p><pre><code>&lt;iframe src=\"https://example.com\" title=\"محتوای خارجی\" sandbox=\"allow-forms\" loading=\"lazy\"&gt;&lt;/iframe&gt;</code></pre><h3>تمرین</h3><p>رفتار iframe محدود را بررسی کن.</p><h3>نکته فنی</h3><p>این قابلیت به‌تنهایی backend یا امنیت کامل ایجاد نمی‌کند؛ رفتار را در مرورگر هدف آزمایش کن و محدودیت آن را در نظر بگیر.</p><h3>معیار موفقیت</h3><ul><li>عنصر و ویژگی با هدف درست انتخاب شده باشد.</li><li>رفتار صفحه با صفحه‌کلید بررسی شده باشد.</li><li>نیاز احتمالی به CSS، JavaScript یا backend را تشخیص بدهی.</li></ul>","starter_code":"<iframe src=\"https://example.com\" title=\"محتوای خارجی\" sandbox=\"allow-forms\" loading=\"lazy\"></iframe>","exercise":"رفتار iframe محدود را بررسی کن.","status":"published","sort_order":24,"estimated_minutes":40},{"id":"curriculum-324-html-intermediate-25","course_id":"html-intermediate","title":"defer و async","slug":"html-intermediate-25","summary":"defer و async: تفاوت اجرای اسکریپت با حفظ ترتیب و اجرای مستقل.","content_html":"<h3>هدف درس</h3><p>تفاوت اجرای اسکریپت با حفظ ترتیب و اجرای مستقل.</p><h3>نمونه کاربردی</h3><p>کد را در فایل HTML آزمایش کن و رفتار آن را در مرورگر بررسی کن.</p><pre><code>&lt;script src=\"app.js\" defer&gt;&lt;/script&gt;&lt;script src=\"metrics.js\" async&gt;&lt;/script&gt;</code></pre><h3>تمرین</h3><p>برای دو اسکریپت با وابستگی متفاوت ویژگی مناسب انتخاب کن.</p><h3>نکته فنی</h3><p>این قابلیت به‌تنهایی backend یا امنیت کامل ایجاد نمی‌کند؛ رفتار را در مرورگر هدف آزمایش کن و محدودیت آن را در نظر بگیر.</p><h3>معیار موفقیت</h3><ul><li>عنصر و ویژگی با هدف درست انتخاب شده باشد.</li><li>رفتار صفحه با صفحه‌کلید بررسی شده باشد.</li><li>نیاز احتمالی به CSS، JavaScript یا backend را تشخیص بدهی.</li></ul>","starter_code":"<script src=\"app.js\" defer></script><script src=\"metrics.js\" async></script>","exercise":"برای دو اسکریپت با وابستگی متفاوت ویژگی مناسب انتخاب کن.","status":"published","sort_order":25,"estimated_minutes":25},{"id":"curriculum-324-html-intermediate-26","course_id":"html-intermediate","title":"JavaScript module","slug":"html-intermediate-26","summary":"JavaScript module: بارگذاری فایل به‌عنوان ماژول با scope مستقل.","content_html":"<h3>هدف درس</h3><p>بارگذاری فایل به‌عنوان ماژول با scope مستقل.</p><h3>نمونه کاربردی</h3><p>کد را در فایل HTML آزمایش کن و رفتار آن را در مرورگر بررسی کن.</p><pre><code>&lt;script type=\"module\" src=\"main.js\"&gt;&lt;/script&gt;</code></pre><h3>تمرین</h3><p>فایل اصلی را به ماژول app.js متصل کن.</p><h3>نکته فنی</h3><p>این قابلیت به‌تنهایی backend یا امنیت کامل ایجاد نمی‌کند؛ رفتار را در مرورگر هدف آزمایش کن و محدودیت آن را در نظر بگیر.</p><h3>معیار موفقیت</h3><ul><li>عنصر و ویژگی با هدف درست انتخاب شده باشد.</li><li>رفتار صفحه با صفحه‌کلید بررسی شده باشد.</li><li>نیاز احتمالی به CSS، JavaScript یا backend را تشخیص بدهی.</li></ul>","starter_code":"<script type=\"module\" src=\"main.js\"></script>","exercise":"فایل اصلی را به ماژول app.js متصل کن.","status":"published","sort_order":26,"estimated_minutes":30},{"id":"curriculum-324-html-intermediate-27","course_id":"html-intermediate","title":"preconnect","slug":"html-intermediate-27","summary":"preconnect: شروع زودهنگام اتصال به مبدأ خارجی موردنیاز.","content_html":"<h3>هدف درس</h3><p>شروع زودهنگام اتصال به مبدأ خارجی موردنیاز.</p><h3>نمونه کاربردی</h3><p>کد را در فایل HTML آزمایش کن و رفتار آن را در مرورگر بررسی کن.</p><pre><code>&lt;link rel=\"preconnect\" href=\"https://fonts.example.com\" crossorigin&gt;</code></pre><h3>تمرین</h3><p>برای منبع خارجی واقعی preconnect تعریف کن.</p><h3>نکته فنی</h3><p>این قابلیت به‌تنهایی backend یا امنیت کامل ایجاد نمی‌کند؛ رفتار را در مرورگر هدف آزمایش کن و محدودیت آن را در نظر بگیر.</p><h3>معیار موفقیت</h3><ul><li>عنصر و ویژگی با هدف درست انتخاب شده باشد.</li><li>رفتار صفحه با صفحه‌کلید بررسی شده باشد.</li><li>نیاز احتمالی به CSS، JavaScript یا backend را تشخیص بدهی.</li></ul>","starter_code":"<link rel=\"preconnect\" href=\"https://fonts.example.com\" crossorigin>","exercise":"برای منبع خارجی واقعی preconnect تعریف کن.","status":"published","sort_order":27,"estimated_minutes":35},{"id":"curriculum-324-html-intermediate-28","course_id":"html-intermediate","title":"preload","slug":"html-intermediate-28","summary":"preload: دریافت زودهنگام منبعی که صفحه به آن نیاز فوری دارد.","content_html":"<h3>هدف درس</h3><p>دریافت زودهنگام منبعی که صفحه به آن نیاز فوری دارد.</p><h3>نمونه کاربردی</h3><p>کد را در فایل HTML آزمایش کن و رفتار آن را در مرورگر بررسی کن.</p><pre><code>&lt;link rel=\"preload\" href=\"/fonts/site.woff2\" as=\"font\" type=\"font/woff2\" crossorigin&gt;</code></pre><h3>تمرین</h3><p>فونت پروژه را با as و type درست preload کن.</p><h3>نکته فنی</h3><p>این قابلیت به‌تنهایی backend یا امنیت کامل ایجاد نمی‌کند؛ رفتار را در مرورگر هدف آزمایش کن و محدودیت آن را در نظر بگیر.</p><h3>معیار موفقیت</h3><ul><li>عنصر و ویژگی با هدف درست انتخاب شده باشد.</li><li>رفتار صفحه با صفحه‌کلید بررسی شده باشد.</li><li>نیاز احتمالی به CSS، JavaScript یا backend را تشخیص بدهی.</li></ul>","starter_code":"<link rel=\"preload\" href=\"/fonts/site.woff2\" as=\"font\" type=\"font/woff2\" crossorigin>","exercise":"فونت پروژه را با as و type درست preload کن.","status":"published","sort_order":28,"estimated_minutes":40},{"id":"curriculum-324-html-intermediate-29","course_id":"html-intermediate","title":"skip link","slug":"html-intermediate-29","summary":"skip link: پرش مستقیم کاربران صفحه‌کلید به محتوای اصلی.","content_html":"<h3>هدف درس</h3><p>پرش مستقیم کاربران صفحه‌کلید به محتوای اصلی.</p><h3>نمونه کاربردی</h3><p>کد را در فایل HTML آزمایش کن و رفتار آن را در مرورگر بررسی کن.</p><pre><code>&lt;a href=\"#main\"&gt;رفتن به محتوا&lt;/a&gt;&lt;nav&gt;...&lt;/nav&gt;&lt;main id=\"main\" tabindex=\"-1\"&gt;...&lt;/main&gt;</code></pre><h3>تمرین</h3><p>لینک پرش بساز و فوکوس مقصد را بررسی کن.</p><h3>نکته فنی</h3><p>این قابلیت به‌تنهایی backend یا امنیت کامل ایجاد نمی‌کند؛ رفتار را در مرورگر هدف آزمایش کن و محدودیت آن را در نظر بگیر.</p><h3>معیار موفقیت</h3><ul><li>عنصر و ویژگی با هدف درست انتخاب شده باشد.</li><li>رفتار صفحه با صفحه‌کلید بررسی شده باشد.</li><li>نیاز احتمالی به CSS، JavaScript یا backend را تشخیص بدهی.</li></ul>","starter_code":"<a href=\"#main\">رفتن به محتوا</a><nav>...</nav><main id=\"main\" tabindex=\"-1\">...</main>","exercise":"لینک پرش بساز و فوکوس مقصد را بررسی کن.","status":"published","sort_order":29,"estimated_minutes":25},{"id":"curriculum-324-html-intermediate-30","course_id":"html-intermediate","title":"tabindex","slug":"html-intermediate-30","summary":"tabindex: کنترل فوکوس برنامه‌ای با مقدار منفی یک یا ترتیب طبیعی با صفر.","content_html":"<h3>هدف درس</h3><p>کنترل فوکوس برنامه‌ای با مقدار منفی یک یا ترتیب طبیعی با صفر.</p><h3>نمونه کاربردی</h3><p>کد را در فایل HTML آزمایش کن و رفتار آن را در مرورگر بررسی کن.</p><pre><code>&lt;h2 id=\"result\" tabindex=\"-1\"&gt;نتیجه&lt;/h2&gt;&lt;button&gt;ادامه&lt;/button&gt;</code></pre><h3>تمرین</h3><p>برای مقصد لینک پرش tabindex منفی یک بگذار.</p><h3>نکته فنی</h3><p>این قابلیت به‌تنهایی backend یا امنیت کامل ایجاد نمی‌کند؛ رفتار را در مرورگر هدف آزمایش کن و محدودیت آن را در نظر بگیر.</p><h3>معیار موفقیت</h3><ul><li>عنصر و ویژگی با هدف درست انتخاب شده باشد.</li><li>رفتار صفحه با صفحه‌کلید بررسی شده باشد.</li><li>نیاز احتمالی به CSS، JavaScript یا backend را تشخیص بدهی.</li></ul>","starter_code":"<h2 id=\"result\" tabindex=\"-1\">نتیجه</h2><button>ادامه</button>","exercise":"برای مقصد لینک پرش tabindex منفی یک بگذار.","status":"published","sort_order":30,"estimated_minutes":30},{"id":"curriculum-324-html-intermediate-31","course_id":"html-intermediate","title":"inert و hidden","slug":"html-intermediate-31","summary":"inert و hidden: inert تعامل زیردرخت را می‌بندد؛ hidden محتوا را از نمایش معمول پنهان می‌کند.","content_html":"<h3>هدف درس</h3><p>inert تعامل زیردرخت را می‌بندد؛ hidden محتوا را از نمایش معمول پنهان می‌کند.</p><h3>نمونه کاربردی</h3><p>کد را در فایل HTML آزمایش کن و رفتار آن را در مرورگر بررسی کن.</p><pre><code>&lt;section hidden&gt;پنل مخفی&lt;/section&gt;&lt;div inert&gt;&lt;button&gt;غیرفعال&lt;/button&gt;&lt;/div&gt;</code></pre><h3>تمرین</h3><p>تفاوت نمایش و تعامل را آزمایش کن.</p><h3>نکته فنی</h3><p>این قابلیت به‌تنهایی backend یا امنیت کامل ایجاد نمی‌کند؛ رفتار را در مرورگر هدف آزمایش کن و محدودیت آن را در نظر بگیر.</p><h3>معیار موفقیت</h3><ul><li>عنصر و ویژگی با هدف درست انتخاب شده باشد.</li><li>رفتار صفحه با صفحه‌کلید بررسی شده باشد.</li><li>نیاز احتمالی به CSS، JavaScript یا backend را تشخیص بدهی.</li></ul>","starter_code":"<section hidden>پنل مخفی</section><div inert><button>غیرفعال</button></div>","exercise":"تفاوت نمایش و تعامل را آزمایش کن.","status":"published","sort_order":31,"estimated_minutes":35},{"id":"curriculum-324-html-intermediate-32","course_id":"html-intermediate","title":"aria-live","slug":"html-intermediate-32","summary":"aria-live: اعلام تغییرات ناحیه پویا به فناوری‌های کمکی.","content_html":"<h3>هدف درس</h3><p>اعلام تغییرات ناحیه پویا به فناوری‌های کمکی.</p><h3>نمونه کاربردی</h3><p>کد را در فایل HTML آزمایش کن و رفتار آن را در مرورگر بررسی کن.</p><pre><code>&lt;p id=\"status\" aria-live=\"polite\" aria-atomic=\"true\"&gt;آماده&lt;/p&gt;&lt;button onclick=\"status.textContent='ذخیره شد'\"&gt;ذخیره&lt;/button&gt;</code></pre><h3>تمرین</h3><p>ناحیه وضعیت پویا بساز و تغییر متن را آزمایش کن.</p><h3>نکته فنی</h3><p>این قابلیت به‌تنهایی backend یا امنیت کامل ایجاد نمی‌کند؛ رفتار را در مرورگر هدف آزمایش کن و محدودیت آن را در نظر بگیر.</p><h3>معیار موفقیت</h3><ul><li>عنصر و ویژگی با هدف درست انتخاب شده باشد.</li><li>رفتار صفحه با صفحه‌کلید بررسی شده باشد.</li><li>نیاز احتمالی به CSS، JavaScript یا backend را تشخیص بدهی.</li></ul>","starter_code":"<p id=\"status\" aria-live=\"polite\" aria-atomic=\"true\">آماده</p><button onclick=\"status.textContent='ذخیره شد'\">ذخیره</button>","exercise":"ناحیه وضعیت پویا بساز و تغییر متن را آزمایش کن.","status":"published","sort_order":32,"estimated_minutes":40},{"id":"curriculum-324-html-intermediate-33","course_id":"html-intermediate","title":"rowspan و colspan","slug":"html-intermediate-33","summary":"rowspan و colspan: گسترش سلول جدول در چند ردیف یا ستون.","content_html":"<h3>هدف درس</h3><p>گسترش سلول جدول در چند ردیف یا ستون.</p><h3>نمونه کاربردی</h3><p>کد را در فایل HTML آزمایش کن و رفتار آن را در مرورگر بررسی کن.</p><pre><code>&lt;table&gt;&lt;tr&gt;&lt;th rowspan=\"2\"&gt;نام&lt;/th&gt;&lt;th colspan=\"2\"&gt;نمره&lt;/th&gt;&lt;/tr&gt;&lt;tr&gt;&lt;th&gt;HTML&lt;/th&gt;&lt;th&gt;CSS&lt;/th&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;سارا&lt;/td&gt;&lt;td&gt;90&lt;/td&gt;&lt;td&gt;85&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;</code></pre><h3>تمرین</h3><p>جدول چندسطحی بساز و سلول‌های منطقی را بشمار.</p><h3>نکته فنی</h3><p>این قابلیت به‌تنهایی backend یا امنیت کامل ایجاد نمی‌کند؛ رفتار را در مرورگر هدف آزمایش کن و محدودیت آن را در نظر بگیر.</p><h3>معیار موفقیت</h3><ul><li>عنصر و ویژگی با هدف درست انتخاب شده باشد.</li><li>رفتار صفحه با صفحه‌کلید بررسی شده باشد.</li><li>نیاز احتمالی به CSS، JavaScript یا backend را تشخیص بدهی.</li></ul>","starter_code":"<table><tr><th rowspan=\"2\">نام</th><th colspan=\"2\">نمره</th></tr><tr><th>HTML</th><th>CSS</th></tr><tr><td>سارا</td><td>90</td><td>85</td></tr></table>","exercise":"جدول چندسطحی بساز و سلول‌های منطقی را بشمار.","status":"published","sort_order":33,"estimated_minutes":25},{"id":"curriculum-324-html-intermediate-34","course_id":"html-intermediate","title":"headers در جدول","slug":"html-intermediate-34","summary":"headers در جدول: ارتباط صریح سلول داده با سرستون‌ها در جدول پیچیده.","content_html":"<h3>هدف درس</h3><p>ارتباط صریح سلول داده با سرستون‌ها در جدول پیچیده.</p><h3>نمونه کاربردی</h3><p>کد را در فایل HTML آزمایش کن و رفتار آن را در مرورگر بررسی کن.</p><pre><code>&lt;table&gt;&lt;tr&gt;&lt;th id=\"student\"&gt;دانش‌آموز&lt;/th&gt;&lt;th id=\"html\"&gt;HTML&lt;/th&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td headers=\"student\"&gt;علی&lt;/td&gt;&lt;td headers=\"html\"&gt;88&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;</code></pre><h3>تمرین</h3><p>جدول نمره با id و headers بساز.</p><h3>نکته فنی</h3><p>این قابلیت به‌تنهایی backend یا امنیت کامل ایجاد نمی‌کند؛ رفتار را در مرورگر هدف آزمایش کن و محدودیت آن را در نظر بگیر.</p><h3>معیار موفقیت</h3><ul><li>عنصر و ویژگی با هدف درست انتخاب شده باشد.</li><li>رفتار صفحه با صفحه‌کلید بررسی شده باشد.</li><li>نیاز احتمالی به CSS، JavaScript یا backend را تشخیص بدهی.</li></ul>","starter_code":"<table><tr><th id=\"student\">دانش‌آموز</th><th id=\"html\">HTML</th></tr><tr><td headers=\"student\">علی</td><td headers=\"html\">88</td></tr></table>","exercise":"جدول نمره با id و headers بساز.","status":"published","sort_order":34,"estimated_minutes":30},{"id":"curriculum-324-html-intermediate-35","course_id":"html-intermediate","title":"time و datetime","slug":"html-intermediate-35","summary":"time و datetime: ارائه تاریخ ماشین‌خوان در کنار متن نمایشی.","content_html":"<h3>هدف درس</h3><p>ارائه تاریخ ماشین‌خوان در کنار متن نمایشی.</p><h3>نمونه کاربردی</h3><p>کد را در فایل HTML آزمایش کن و رفتار آن را در مرورگر بررسی کن.</p><pre><code>&lt;time datetime=\"2026-11-07\"&gt;۷ نوامبر ۲۰۲۶&lt;/time&gt;</code></pre><h3>تمرین</h3><p>تاریخ و ساعت رویداد را با datetime معتبر نمایش بده.</p><h3>نکته فنی</h3><p>این قابلیت به‌تنهایی backend یا امنیت کامل ایجاد نمی‌کند؛ رفتار را در مرورگر هدف آزمایش کن و محدودیت آن را در نظر بگیر.</p><h3>معیار موفقیت</h3><ul><li>عنصر و ویژگی با هدف درست انتخاب شده باشد.</li><li>رفتار صفحه با صفحه‌کلید بررسی شده باشد.</li><li>نیاز احتمالی به CSS، JavaScript یا backend را تشخیص بدهی.</li></ul>","starter_code":"<time datetime=\"2026-11-07\">۷ نوامبر ۲۰۲۶</time>","exercise":"تاریخ و ساعت رویداد را با datetime معتبر نمایش بده.","status":"published","sort_order":35,"estimated_minutes":35},{"id":"curriculum-324-html-intermediate-36","course_id":"html-intermediate","title":"پروژه پایانی داشبورد آموزشی","slug":"html-intermediate-36","summary":"پروژه پایانی داشبورد آموزشی: ترکیب فرم گروه‌بندی‌شده، progress، details، تصویر واکنش‌گرا و اعلان وضعیت در یک رابط.","content_html":"<h3>هدف درس</h3><p>ترکیب فرم گروه‌بندی‌شده، progress، details، تصویر واکنش‌گرا و اعلان وضعیت در یک رابط.</p><h3>نمونه کاربردی</h3><p>کد را در فایل HTML آزمایش کن و رفتار آن را در مرورگر بررسی کن.</p><pre><code>&lt;!doctype html&gt;&lt;html lang=\"fa\" dir=\"rtl\"&gt;&lt;head&gt;&lt;meta charset=\"UTF-8\"&gt;&lt;meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"&gt;&lt;title&gt;داشبورد دوره&lt;/title&gt;&lt;/head&gt;&lt;body&gt;&lt;a href=\"#main\"&gt;رفتن به محتوا&lt;/a&gt;&lt;header&gt;&lt;h1&gt;داشبورد دوره&lt;/h1&gt;&lt;/header&gt;&lt;main id=\"main\" tabindex=\"-1\"&gt;&lt;section&gt;&lt;h2&gt;پیشرفت&lt;/h2&gt;&lt;progress value=\"6\" max=\"10\"&gt;60%&lt;/progress&gt;&lt;/section&gt;&lt;form&gt;&lt;fieldset&gt;&lt;legend&gt;مسیر آموزشی&lt;/legend&gt;&lt;select&gt;&lt;optgroup label=\"وب\"&gt;&lt;option&gt;HTML&lt;/option&gt;&lt;option&gt;CSS&lt;/option&gt;&lt;/optgroup&gt;&lt;/select&gt;&lt;/fieldset&gt;&lt;button&gt;ثبت آزمایشی&lt;/button&gt;&lt;/form&gt;&lt;details&gt;&lt;summary&gt;راهنما&lt;/summary&gt;&lt;p&gt;درس بعدی را باز کن.&lt;/p&gt;&lt;/details&gt;&lt;p aria-live=\"polite\"&gt;آماده&lt;/p&gt;&lt;/main&gt;&lt;/body&gt;&lt;/html&gt;</code></pre><h3>تمرین</h3><p>داشبوردی با skip link، progress، fieldset، optgroup، details، picture، جدول چندسطحی و aria-live بساز و با صفحه‌کلید و اعتبارسنج HTML بررسی کن.</p><h3>نکته فنی</h3><p>این قابلیت به‌تنهایی backend یا امنیت کامل ایجاد نمی‌کند؛ رفتار را در مرورگر هدف آزمایش کن و محدودیت آن را در نظر بگیر.</p><h3>معیار موفقیت</h3><ul><li>عنصر و ویژگی با هدف درست انتخاب شده باشد.</li><li>رفتار صفحه با صفحه‌کلید بررسی شده باشد.</li><li>نیاز احتمالی به CSS، JavaScript یا backend را تشخیص بدهی.</li></ul>","starter_code":"<!doctype html><html lang=\"fa\" dir=\"rtl\"><head><meta charset=\"UTF-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>داشبورد دوره</title></head><body><a href=\"#main\">رفتن به محتوا</a><header><h1>داشبورد دوره</h1></header><main id=\"main\" tabindex=\"-1\"><section><h2>پیشرفت</h2><progress value=\"6\" max=\"10\">60%</progress></section><form><fieldset><legend